  ["data.otservbr.global.npc.a.fluffy.squirrel.L74.1055"] = "Chchch. Chh! <nie jesteś pewien, ale wygląda na to, że wiewiórka chce wymienić twoje cenne żołędzie na bezużyteczne kamienie, które znalazła i uznała za niejadalne>",
  ["data.otservbr.global.npc.a.frog.L57.1456"] = "*wzdycha* Kolejny głupi poszukiwacz przygód.",
  ["data.otservbr.global.npc.a.frog.L58.1457"] = "Ta, do widzenia i nie wracaj!",
  ["data.otservbr.global.npc.a.frog.L59.1458"] = "Ha! Ten idiota wreszcie poszedł.",
  ["data.otservbr.global.npc.a.ghostly.sage.L60.1103"] = "Ach, czuję, że znów śmiertelnik przemierza te starożytne hale. Wybacz mi, ledwo cię zauważam. Tak bardzo ginę we własnych myślach.",
  ["data.otservbr.global.npc.a.ghostly.sage.L61.1104"] = "Do widzenia.",
  ["data.otservbr.global.npc.a.ghostly.sage.L62.1105"] = "Żegnaj zatem.",
  ["data.otservbr.global.npc.a.ghostly.woman.L62.1178"] = "Czuję cię. Słyszę twoje myśli. Jesteś... żywy.",
  ["data.otservbr.global.npc.a.ghostly.woman.L63.1179"] = "Sam... zupełnie sam. Tak zimno.",
