  ["data.otservbr.global.npc.a.prisoner.L138.261"] = "Czekaj! Nie odchodź! Chcę ci opowiedzieć o moich liczbach surrealnych.",
  ["data.otservbr.global.npc.a.prisoner.L139.262"] = "Do widzenia! Nie zapomnij o sekretach matemagii.",
  ["data.otservbr.global.npc.a.prisoner.L140.263"] = "Co? Jak? Widzę! Wow! Nie-minotaur. Czy oni też cię {capture}?",
  ["data.otservbr.global.npc.a.restless.soul.L53.44"] = "Uuuuhhh...",
  ["data.otservbr.global.npc.a.restless.soul.L56.45"] = "[PL] Ahhhh! At last someone that can listen to my {story}!",
  ["data.otservbr.global.npc.a.sleeping.dragon.L51.150"] = "Zzzz... chrrr...",
  ["data.otservbr.global.npc.a.sleeping.dragon.L53.151"] = "Pozdrowienia, {wayfarer}.",
  ["data.otservbr.global.npc.a.strange.chalice.L117.1623"] = "Cześć? Co masz na myśli 'hi' - nie widzisz, że jestem... Muszę ściszyć głos. Czy przyszło Ci do głowy, że ten 'chalice' nie chce, żeby mu przeszkadzano?! Zostaw mnie w spokoju!",
  ["data.otservbr.global.npc.a.swan.L95.88"] = "Pozdrawiam cię, śmiertelna istoto.",
