  ["data.otservbr.global.npc.a.weakened.forest.fury.L122.711"] = "Witam cię, człowieku. To czas udręki, bardziej niż kiedykolwiek potrzebujemy strażników, by chronili nas i nasz świat.",
  ["data.otservbr.global.npc.a.wrinkled.bonelord.L80.1421"] = "Cóż to? Istota z problemami wzroku zwąca się |PLAYERNAME|. Jak fascynujące!",
  ["data.otservbr.global.npc.a.wrinkled.bonelord.L81.1422"] = "Zaczekaj tam. Zjem cię, kiedy tylko zapiszę to, czego się dowiedziałem.",
  ["data.otservbr.global.npc.a.wrinkled.bonelord.L82.1423"] = "Zaczekaj tam. Zjem cię, kiedy tylko zapiszę to, czego się dowiedziałem.",
