  ["data.otservbr.global.npc.ahmet.L182.407"] = "Bądź opłakany, pielgrzymie w ciele. Sprzedaję towary ogólne. Po prostu zapytaj o {trade}.",
  ["data.otservbr.global.npc.ajax.L58.355"] = "Wróciłeś. Wiesz, masz rację. Brat ma rację. Pięść nie zawsze jest dobra. Powiedz mu to!",
  ["data.otservbr.global.npc.ajax.L61.356"] = "Co robisz u mnie?",
  ["data.otservbr.global.npc.al.dee.L166.596"] = "Pa, pa.",
  ["data.otservbr.global.npc.al.dee.L167.597"] = "Pa, pa |PLAYERNAME|.",
  ["data.otservbr.global.npc.al.dee.L168.598"] = "Spójrz do okna handlu po lewej stronie.",
  ["data.otservbr.global.npc.albinius.L267.1035"] = "Pozdrowienia, pielgrzymie. Witaj w halach nadziei. Jesteśmy strażnikami tej {temple} i witamy każdego chętnego do wsparcia.",
  ["data.otservbr.global.npc.albinius.L268.1036"] = "Och... żegnaj, dziecko.",
  ["data.otservbr.global.npc.alesar.L206.1591"] = "W końcu.",
  ["data.otservbr.global.npc.alesar.L207.1592"] = "W końcu.",
  ["data.otservbr.global.npc.alesar.L208.1593"] = "Do usług, przejrzyj moje towary.",
  ["data.otservbr.global.npc.alexander.L171.1567"] = "[PL] Hi there |PLAYERNAME|, and welcome to the {magic} store.",
  ["data.otservbr.global.npc.alexander.L172.1568"] = "Do zobaczenia, |PLAYERNAME|.",
  ["data.otservbr.global.npc.alexander.L173.1569"] = "Do zobaczenia, |PLAYERNAME|.",
  ["data.otservbr.global.npc.alexander.L174.1570"] = "Oczywiście, przejrzyj moje towary. A może chcesz zobaczyć tylko",
  ["data.otservbr.global.npc.alia.L148.1158"] = "Witaj, młody |PLAYERNAME|! Jeśli jesteś ciężko ranny lub zatruty, mogę cię za darmo {heal}.",
  ["data.otservbr.global.npc.alia.L149.1159"] = "Pamiętaj: jeśli jesteś ciężko ranny lub zatruty, mogę cię uleczyć za darmo.",
  ["data.otservbr.global.npc.alia.L150.1160"] = "Niech bogowie ci błogosławią, |PLAYERNAME|!",
  ["data.otservbr.global.npc.alkestios.L130.1473"] = "Błogosławieństwo natury, podróżniku! Oby nie dotknęła cię żadna złowroga siła.",
  ["data.otservbr.global.npc.alkestios.L131.1474"] = "Niech twoja droga zawsze będzie równa.",
  ["data.otservbr.global.npc.alkestios.L132.1475"] = "Niech twoja droga zawsze będzie równa.",
  ["data.otservbr.global.npc.altar.L83.730"] = "Klęknij przed wszechpożerającą mocą krwawego rozkładu.",
