  ["data.otservbr.global.npc.altar.L85.732"] = "Do widzenia, |PLAYERNAME|.",
  ["data.otservbr.global.npc.alyxo.L210.798"] = "No to cześć.",
  ["data.otservbr.global.npc.alyxo.L53.795"] = "Jak mogę pomóc?",
  ["data.otservbr.global.npc.alyxo.L56.796"] = "Jak mogę pomóc?",
  ["data.otservbr.global.npc.alyxo.L59.797"] = "Jak mogę pomóc?",
  ["data.otservbr.global.npc.amanda.L200.1226"] = "Witaj, młody |PLAYERNAME|! Jeśli jesteś ciężko ranny lub zatruty, mogę cię za darmo {heal}.",
  ["data.otservbr.global.npc.amanda.L201.1227"] = "Pamiętaj: jeśli jesteś ciężko ranny lub zatruty, mogę cię uleczyć za darmo.",
  ["data.otservbr.global.npc.amanda.L202.1228"] = "Niech bogowie ci błogosławią, |PLAYERNAME|!",
  ["data.otservbr.global.npc.ambassador.of.rathleton.L86.343"] = "Pozdrowienia, przyjacielu.",
  ["data.otservbr.global.npc.ambassador.of.rathleton.L87.344"] = "No to cześć.",
  ["data.otservbr.global.npc.amber.L426.528"] = "Ta, do zobaczenia.",
  ["data.otservbr.global.npc.amber.L427.529"] = "Do zobaczenia później, |PLAYERNAME|.",
  ["data.otservbr.global.npc.amber.L428.530"] = "O, cześć, miło cię widzieć |PLAYERNAME|. Przyszedłeś posłuchać historii moich {adventures}, czy potrzebujesz {help}?",
  ["data.otservbr.global.npc.anderson.L100.133"] = "Ahoj, młodzieńcze |PLAYERNAME|, witaj na Nordyckich Promach Tibii. Jeśli potrzebujesz {passage}, daj znać.",
  ["data.otservbr.global.npc.anderson.L101.134"] = "Do widzenia. Zapraszamy ponownie.",
  ["data.otservbr.global.npc.andrew.lyze.L101.514"] = "Witaj, jestem strażnikiem tego {monument}. {sarcophagus} przed tobą ustanowiono, by powstrzymać ludzi przed schodzeniem {down} tam. Ale wątpię, by to wystarczało.",
  ["data.otservbr.global.npc.andrew.lyze.L103.515"] = "Dobrze, zobaczmy, czy twoja misja się powiodła. Przynieś mi wszystkie potrzebne {materials}.",
  ["data.otservbr.global.npc.andrew.lyze.L105.516"] = "Jeśli wykopałeś wszystkie trzy kryształy w odpowiedniej ilości i zdobyłeś gruczoł jadu, ładowanie kompasu może się zacząć! Po raz pierwszy zostanie naładowany fioletowym kryształem. Gotów {unleash} moc kryształów?",
  ["data.otservbr.global.npc.andrew.lyze.L107.517"] = "Pozdrowienia.",
  ["data.otservbr.global.npc.andrew.lyze.L263.518"] = "No to cześć.",
  ["data.otservbr.global.npc.andrew.lyze.L264.519"] = "Do widzenia.",
  ["data.otservbr.global.npc.anerui.L71.1487"] = "Ashari, |PLAYERNAME|.",
  ["data.otservbr.global.npc.anerui.L72.1488"] = "Asha Thrazi!",
  ["data.otservbr.global.npc.anerui.L73.1489"] = "Asha Thrazi!",
  ["data.otservbr.global.npc.aneus.L130.1323"] = "Pozdrowienia, poszukiwaczu przygód |PLAYERNAME|. Co cię do mnie sprowadza?",
  ["data.otservbr.global.npc.aneus.L131.1324"] = "Do widzenia i dbaj o siebie!",
  ["data.otservbr.global.npc.angelina.L58.143"] = "Bogów trzeba wielbić, że wreszcie zostałam uratowana. Nie mam wielu dóbr doczesnych, ale proszę, przyjmij małą nagrodę, dobrze?",
  ["data.otservbr.global.npc.angelina.L60.144"] = "Dzięki za uratowanie mi życia! Czy mam teleportować cię z Dark Cathedral?",
  ["data.otservbr.global.npc.angelina.L84.145"] = "Niech bogowie ci błogosławią.",
  ["data.otservbr.global.npc.angelina.L85.146"] = "Niech bogowie ci błogosławią.",
  ["data.otservbr.global.npc.angelo.L153.1447"] = "No to cześć.",
  ["data.otservbr.global.npc.angelo.L58.1443"] = "Druid Crunora? Powiedział ci, że pojawiła się tu nowa jaskinia? Zgadza się. Kieruję {project}, który próbuje dowiedzieć się więcej o tym nowym {area}.",
  ["data.otservbr.global.npc.angelo.L60.1444"] = "Zejdź mi z drogi! Zabiłeś to piękne stworzenie. Nie mam ci nic więcej do powiedzenia. Przeklęty druidzie Crunora!",
  ["data.otservbr.global.npc.angelo.L62.1445"] = "Jak idzie twoja {mission}?",
  ["data.otservbr.global.npc.angelo.L64.1446"] = "Druid Crunora? Powiedział ci, że pojawiła się tu nowa jaskinia? Zgadza się. Kieruję projektem, który próbuje dowiedzieć się więcej o tym nowym obszarze.",
  ["data.otservbr.global.npc.angus.L633.1450"] = "Pozdrowienia, co mogę dla ciebie zrobić?",
  ["data.otservbr.global.npc.appaloosa.L109.1145"] = "Witaj, |PLAYERNAME|. Domyślam się, że jesteś tu w sprawie {horses}.",
  ["data.otservbr.global.npc.archery.L64.538"] = "Witaj w sklepie Archery!",
  ["data.otservbr.global.npc.archery.L65.539"] = "Wpadaj od czasu do czasu.",
  ["data.otservbr.global.npc.archery.L66.540"] = "Wpadaj od czasu do czasu.",
  ["data.otservbr.global.npc.archery.rook.L63.70"] = "Witaj w sklepie Archery na Rookgaardzie.",
  ["data.otservbr.global.npc.archery.rook.L64.71"] = "Wpadaj od czasu do czasu.",
  ["data.otservbr.global.npc.archery.rook.L65.72"] = "Wpadaj od czasu do czasu.",
  ["data.otservbr.global.npc.ariella.L161.242"] = "Cześć.",
  ["data.otservbr.global.npc.arito.L117.1343"] = "Odwiedź nas ponownie.",
  ["data.otservbr.global.npc.arito.L118.1344"] = "Odwiedź nas ponownie.",
  ["data.otservbr.global.npc.arito.L119.1345"] = "Jasne, przejrzyj moje oferty.",
  ["data.otservbr.global.npc.arito.L55.1341"] = "Dzięki bogom, wróciłeś!! Znalazłeś....eee...to, o czym rozmawialiśmy??",
  ["data.otservbr.global.npc.arito.L57.1342"] = "Bądź opłakany, pielgrzymie w ciele. Bądź opłakany w mojej tawernie.",
  ["data.otservbr.global.npc.arkarra.L54.501"] = "(...)",
  ["data.otservbr.global.npc.arkarra.L55.502"] = "(...)",
  ["data.otservbr.global.npc.arkarra.L56.503"] = "(...)",
  ["data.otservbr.global.npc.arkulius.L183.893"] = "Do widzenia i trzymaj się z daleka, dobrze?",
  ["data.otservbr.global.npc.arkulius.L184.894"] = "Wreszcie! Dobre rzeczy przychodzą do tych, którzy czekają.",
  ["data.otservbr.global.npc.armenius.L74.643"] = "Co za tupet. Idź do szczurów, które cię wychowały.",
  ["data.otservbr.global.npc.armenius.L86.644"] = "Ach, poszukiwaczu przygód. Bądź pozdrowiony i usiądź. Jak mogę cię {serve}?",
  ["data.otservbr.global.npc.aruda.L256.1338"] = "Mam nadzieję, że wkrótce cię zobaczę.",
  ["data.otservbr.global.npc.aruda.L257.1339"] = "Do widzenia, |PLAYERNAME|. Naprawdę mam nadzieję, że wkrótce znów porozmawiamy.",
  ["data.otservbr.global.npc.aruda.L64.1336"] = "O, cześć |PLAYERNAME|, świetnie wyglądają twoje włosy! Kto ci je zrobił?",
  ["data.otservbr.global.npc.aruda.L67.1337"] = "O, cześć, przystojniaku! Miło cię poznać, |PLAYERNAME|. Chętnie znajdę chwilę, by {chat}.",
  ["data.otservbr.global.npc.ashari.L52.1581"] = "Witaj, nieznajomy! Te jaskinie muszą wydawać ci się dziwne. Ciekawe, co cię tu sprowadza... może interesuje cię jakaś praca? Mam kilka zadań, przydałaby mi się pomoc.",
  ["data.otservbr.global.npc.ashari.L53.1582"] = "Pa!",
  ["data.otservbr.global.npc.ashari.L54.1583"] = "Pa!",
  ["data.otservbr.global.npc.asima.L179.1417"] = "Oczywiście, przejrzyj moje towary. A może chcesz zobaczyć tylko",
  ["data.otservbr.global.npc.atur.L76.727"] = "Tak? Co mogę dla ciebie zrobić, |PLAYERNAME|? Może sprawy bankowe?",
  ["data.otservbr.global.npc.atur.L77.728"] = "Miłego dnia.",
  ["data.otservbr.global.npc.atur.L78.729"] = "Miłego dnia.",
  ["data.otservbr.global.npc.aurita.L114.171"] = "Pozdrowienia, podróżniku!",
  ["data.otservbr.global.npc.aurita.L115.172"] = "Niech twoja droga zawsze będzie równa.",
  ["data.otservbr.global.npc.aurita.L116.173"] = "Niech twoja droga zawsze będzie równa.",
  ["data.otservbr.global.npc.avar.tar.L137.859"] = "Pozdrowienia, podróżniku |PLAYERNAME|!",
  ["data.otservbr.global.npc.avar.tar.L138.860"] = "Do zobaczenia później, |PLAYERNAME|.",
  ["data.otservbr.global.npc.avar.tar.L139.861"] = "Do zobaczenia później, |PLAYERNAME|.",
  ["data.otservbr.global.npc.awarness.of.the.emperor.L50.141"] = "Nie jestem tu, by z tobą walczyć, głupcze. Czy ci się to podoba czy nie, musimy współpracować, by powstrzymać katastrofę, którą wywołaliście ty i ten kapłan.",
  ["data.otservbr.global.npc.awarness.of.the.emperor.L52.142"] = "Pozdrowienia, śmiertelniku. Uważaj, bo wystawiasz moją cierpliwość na próbę, gdy rozmawiamy.",
  ["data.otservbr.global.npc.azalea.L148.851"] = "Witaj, młody |PLAYERNAME|! Jeśli jesteś ciężko ranny lub zatruty, mogę cię za darmo {heal}.",
  ["data.otservbr.global.npc.azalea.L149.852"] = "Pamiętaj: jeśli jesteś ciężko ranny lub zatruty, mogę cię uleczyć za darmo.",
  ["data.otservbr.global.npc.azalea.L150.853"] = "Niech bogowie ci błogosławią, |PLAYERNAME|!",
  ["data.otservbr.global.npc.baa.leal.L158.273"] = "Spocznij, żołnierzu!",
  ["data.otservbr.global.npc.bambi.bonecrusher.L76.573"] = "NIECH ŻYJE KRÓLOWA!",
  ["data.otservbr.global.npc.bambi.bonecrusher.L77.574"] = "NIECH ŻYJE KRÓLOWA!",
  ["data.otservbr.global.npc.bambi.bonecrusher.L78.575"] = "NIECH ŻYJE KRÓLOWA!",
  ["data.otservbr.global.npc.barazbaz.L93.18"] = "O, witaj!",
  ["data.otservbr.global.npc.barbara.L84.1299"] = "NIECH ŻYJE KRÓLOWA!",
  ["data.otservbr.global.npc.barbara.L85.1300"] = "NIECH ŻYJE KRÓLOWA! Możesz już odejść!",
  ["data.otservbr.global.npc.barnabas.dee.L130.1046"] = "Witaj w moim skromnym domostwie. Jeśli szukasz nowych czarodziejskich {spells}, trafiłeś we właściwe miejsce.",
  ["data.otservbr.global.npc.barnabas.dee.L131.1047"] = "Uważaj, dziecko.",
  ["data.otservbr.global.npc.barnabas.dee.L132.1048"] = "\"Porywczość młodości\", jak powiedziałby mój przyjaciel Mordecai.",
  ["data.otservbr.global.npc.bashira.L63.1584"] = "Witaj, |PLAYERNAME|.",
  ["data.otservbr.global.npc.bashira.L64.1585"] = "Do widzenia, |PLAYERNAME|.",
  ["data.otservbr.global.npc.bashira.L65.1586"] = "Niech Bóg wskaże ci drogę, |PLAYERNAME|.",
  ["data.otservbr.global.npc.bashira.L66.1587"] = "Oczywiście, przejrzyj moje oferty.",
  ["data.otservbr.global.npc.battlemart.L64.1360"] = "Dobrze cię widzieć. Zawsze jestem do twojej dyspozycji w {shop options}",
  ["data.otservbr.global.npc.battlemart.L65.1361"] = "Żegnaj, |PLAYERNAME|, będę tu, jeśli znów będziesz mnie potrzebować.",
  ["data.otservbr.global.npc.battlemart.L66.1362"] = "Wróć wkrótce!",
  ["data.otservbr.global.npc.battlemart.L67.1363"] = "Oczywiście, przejrzyj moje towary. A może chcesz zobaczyć tylko",
  ["data.otservbr.global.npc.baxter.L60.1236"] = "NIECH ŻYJE KRÓL TIBIANUS!",
  ["data.otservbr.global.npc.baxter.L61.1237"] = "NIECH ŻYJE KRÓL!",
  ["data.otservbr.global.npc.baxter.L62.1238"] = "NIECH ŻYJE KRÓL!",
  ["data.otservbr.global.npc.baxter.L63.1239"] = "Przynosisz świeżo zabite szczury po 1 sztukę złota za każdy? Przy okazji kupuję też orcze zęby i inne rzeczy, które wyrwałeś z ich zakrwawionych cia... znaczy... no, wiesz o co chodzi.",
  ["data.otservbr.global.npc.beatrice.L87.769"] = "Do zobaczenia później, |PLAYERNAME|.",
  ["data.otservbr.global.npc.beatrice.L88.770"] = "Do zobaczenia później, |PLAYERNAME|.",
  ["data.otservbr.global.npc.beatrice.L89.771"] = "Oczywiście, przejrzyj moje towary.",
  ["data.otservbr.global.npc.benjamin.L84.240"] = "[PL] Hello. How may I help you |PLAYERNAME|? Ask me for a {trade} if you want to buy something. I can also explain the {mail} system.",
  ["data.otservbr.global.npc.benjamin.L85.241"] = "To była przyjemność ci pomóc.",
  ["data.otservbr.global.npc.bertha.L88.1552"] = "Och, wejdź proszę, |PLAYERNAME|. Co mogę dla ciebie zrobić? Jeśli potrzebujesz sprzętu na wyprawę, poproś o {trade}.",
  ["data.otservbr.global.npc.bertha.L89.1553"] = "Do widzenia, |PLAYERNAME|.",
  ["data.otservbr.global.npc.bertha.L90.1554"] = "Do widzenia, |PLAYERNAME|.",
  ["data.otservbr.global.npc.bertha.L91.1555"] = "Oczywiście, przejrzyj moje towary. {Footballs} trzeba kupić osobno.",
  ["data.otservbr.global.npc.billy.L144.1384"] = "ALE NIEGRZECZNIE!",
  ["data.otservbr.global.npc.billy.L145.1385"] = "Cześć.",
  ["data.otservbr.global.npc.billy.L146.1386"] = "Jasne.",
  ["data.otservbr.global.npc.billy.L147.1387"] = "Czołem |PLAYERNAME|. Jestem farmerem i kucharzem, może zainteresuje cię {trade} jedzeniem? Możesz też zapytać mnie o ogólne {hints} dotyczące gry.",
  ["data.otservbr.global.npc.black.bert.L196.40"] = "[PL] Hi there, |PLAYERNAME|! You look like you are eager to {trade}!",
  ["data.otservbr.global.npc.black.bert.L197.41"] = "Pa, |PLAYERNAME|.",
  ["data.otservbr.global.npc.blind.orc.L102.1517"] = "Futchi!",
  ["data.otservbr.global.npc.bloodshade.rotten.L72.427"] = "Śmiertelniku! Jeśli jesteś na {quest}, by służyć bogu krwi, mojemu panu - bądź pozdrowiony!",
  ["data.otservbr.global.npc.bloodshade.rotten.L73.428"] = "Cześć.",
  ["data.otservbr.global.npc.bloodshade.rotten.L74.429"] = "Do widzenia, |PLAYERNAME|.",
