  ["data.otservbr.global.npc.blossom.bonecrusher.L78.844"] = "NIECH ŻYJE KRÓLOWA!",
  ["data.otservbr.global.npc.bo.ques.L168.1459"] = "Do widzenia. Jestem pewien, że wrócisz po więcej. Wszyscy tak robią.",
  ["data.otservbr.global.npc.bo.ques.L169.1460"] = "Do widzenia. Jestem pewien, że wrócisz po więcej. Wszyscy tak robią.",
  ["data.otservbr.global.npc.bolfona.L91.688"] = "Do zobaczenia, przyjacielu.",
  ["data.otservbr.global.npc.bolfona.L92.689"] = "Do zobaczenia, przyjacielu.",
  ["data.otservbr.global.npc.bolfona.L94.690"] = "Czy mówisz do mnie? Cóż, rozmawiaj dalej, ale nie oczekuj odpowiedzi.",
  ["data.otservbr.global.npc.boozer.L84.615"] = "[PL] Welcome to the Hard Rock Racing Track, |PLAYERNAME|.",
  ["data.otservbr.global.npc.boveas.L44.24"] = "Cześć! Mam nadzieję, że nie zamierzasz mnie zabić!",
  ["data.otservbr.global.npc.boveas.L45.25"] = "Do widzenia, |PLAYERNAME|.",
  ["data.otservbr.global.npc.boveas.L46.26"] = "Do widzenia, |PLAYERNAME|.",
  ["data.otservbr.global.npc.bozo.L608.916"] = "Hej, jak tam wisi, |PLAYERNAME|! Co cię tu {here} sprowadza?",
  ["data.otservbr.global.npc.bozo.L610.917"] = "Witaj, witaj, witaj, mała damo |PLAYERNAME|! Co cię {here} sprowadza?",
  ["data.otservbr.global.npc.bozo.L922.918"] = "Pamiętaj: żart dziennie trzyma ghule z daleka!",
  ["data.otservbr.global.npc.bozo.L923.919"] = "Hej! Głupcy też mają uczucia.",
