  ["data.otservbr.global.npc.brasith.L61.1213"] = "Asha Thrazi!",
  ["data.otservbr.global.npc.brewster.L185.1484"] = "Witaj, młody |PLAYERNAME|! Jeśli jesteś ciężko ranny lub zatruty, mogę cię za darmo {heal}.",
  ["data.otservbr.global.npc.brewster.L186.1485"] = "Pamiętaj: jeśli jesteś ciężko ranny lub zatruty, mogę cię uleczyć za darmo.",
  ["data.otservbr.global.npc.brewster.L187.1486"] = "Niech bogowie ci błogosławią, |PLAYERNAME|!",
  ["data.otservbr.global.npc.brodrosch.L134.319"] = "Witaj, |PLAYERNAME|! Niech ziemia cię chroni na skalistych terenach. Jeśli potrzebujesz {passage}, mogę pomóc.",
  ["data.otservbr.global.npc.brodrosch.L135.320"] = "Do widzenia.",
  ["data.otservbr.global.npc.brodrosch.L136.321"] = "W takim razie do widzenia.",
  ["data.otservbr.global.npc.broken.servant.sentry.L125.702"] = "Mistrz je-je-jest mar-twy. Pro-pro*chrrrrchk*sze. Bądźcie. W. Żałobie.",
  ["data.otservbr.global.npc.bron.L188.28"] = "Witaj w mojej skromnej chatce, |PLAYERNAME|.",
  ["data.otservbr.global.npc.bron.L192.29"] = "Uważaj, |PLAYERNAME|!",
  ["data.otservbr.global.npc.bron.L193.30"] = "Trzymaj się!",
  ["data.otservbr.global.npc.bron.L58.27"] = "O nie! To naprawdę ja? Jakie to żenujące, nie mam pojęcia, co we mnie wstąpiło. Czy to był duch walki, który mi dałeś?",
  ["data.otservbr.global.npc.bruno.L61.437"] = "Ahoj, |PLAYERNAME|. Chcesz kupić świeżą rybę?",
  ["data.otservbr.global.npc.bruno.L62.438"] = "Do widzenia i zapraszam ponownie!",
  ["data.otservbr.global.npc.bruno.L63.439"] = "Kupuj rybę ile chcesz. Świeża i zdrowa, obiecuję.",
  ["data.otservbr.global.npc.buddel.L134.211"] = "Hej, duże chłopaki. Ty? {Here}? *HICK*",
  ["data.otservbr.global.npc.buddel.helheim.L130.794"] = "[PL] Where are we at the moment? Is this {Svargrond}? NO,*HICKS* it's Helheim! Anyway, where do you want to go?",
  ["data.otservbr.global.npc.buddel.okolnir.L134.1427"] = "[PL] Where are we at the moment? Is this {Svargrond}? NO,*HICKS* it's Okolnir! Anyway, where do you want to go?",
  ["data.otservbr.global.npc.buddel.raider.camp.L135.1246"] = "[PL] Where are we at the moment? Is this {Svargrond}? NO,*HICKS* it's Camp! Anyway, where do you want to go?",
  ["data.otservbr.global.npc.buddel.tyrsung.L135.726"] = "[PL] Where are we at the moment? Is this {Svargrond}? NO,*HICKS* it's Tyrsung! Anyway, where do you want to go?",
  ["data.otservbr.global.npc.budrik.L152.723"] = "Pa, pa.",
  ["data.otservbr.global.npc.budrik.L153.724"] = "Pa, pa.",
  ["data.otservbr.global.npc.budrik.L154.725"] = "[PL] Hiho, hiho |PLAYERNAME|. Why do you {disturb} me?",
  ["data.otservbr.global.npc.bunny.bonecrusher.L111.102"] = "Zwracaj się do mnie odpowiednio, |PLAYERNAME|!",
  ["data.otservbr.global.npc.bunny.bonecrusher.L112.103"] = "NIECH ŻYJE KRÓLOWA!",
  ["data.otservbr.global.npc.bunny.bonecrusher.L113.104"] = "NIECH ŻYJE KRÓLOWA!",
  ["data.otservbr.global.npc.busty.bonecrusher.L82.1290"] = "NIECH ŻYJE KRÓLOWA!",
  ["data.otservbr.global.npc.busty.bonecrusher.L83.1291"] = "NIECH ŻYJE KRÓLOWA!",
  ["data.otservbr.global.npc.busty.bonecrusher.L84.1292"] = "NIECH ŻYJE KRÓLOWA!",
  ["data.otservbr.global.npc.cael.L392.236"] = "Pozdrowienia, |PLAYERNAME|! Musiałeś sporo podróżować. Zawsze chętnie poznaję nowe rzeczy o Zao.",
  ["data.otservbr.global.npc.cael.L393.237"] = "Pamiętaj, że nie znajdziesz tu lepszych ofert. Po prostu przejrzyj moje towary.",
  ["data.otservbr.global.npc.canary.L124.458"] = "Ta, do widzenia i nie wracaj!",
  ["data.otservbr.global.npc.canary.L126.459"] = "Ty nie mieć edukacja?",
  ["data.otservbr.global.npc.canary.L88.457"] = "Witaj |PLAYERNAME|, potrzebujesz więcej informacji o {canary}?",
  ["data.otservbr.global.npc.captain.bluebear.L118.99"] = "[PL] Welcome on board, |PLAYERNAME|. Where can I {sail} you today?",
  ["data.otservbr.global.npc.captain.bluebear.L119.100"] = "Do widzenia. Poleć nas, jeśli byłeś zadowolony z naszej obsługi.",
  ["data.otservbr.global.npc.captain.bluebear.L120.101"] = "W takim razie do widzenia.",
  ["data.otservbr.global.npc.captain.breezelda.L73.336"] = "[PL] Welcome on board, |PLAYERNAME|. Where can I {sail} you today?",
  ["data.otservbr.global.npc.captain.breezelda.L74.337"] = "Do widzenia. Poleć nas, jeśli byłeś zadowolony z naszej obsługi.",
  ["data.otservbr.global.npc.captain.breezelda.L75.338"] = "W takim razie do widzenia.",
  ["data.otservbr.global.npc.captain.chelop.L75.1609"] = "Witamy na pokładzie, rekrucie |PLAYERNAME|. Dokąd mam cię dziś {sail}?",
  ["data.otservbr.global.npc.captain.chelop.L76.1610"] = "W imieniu inkwizycji żegnam cię.",
  ["data.otservbr.global.npc.captain.chelop.L77.1611"] = "W takim razie do widzenia.",
  ["data.otservbr.global.npc.captain.cookie.L64.993"] = "Pozdrowienia, śmiały poszukiwaczu przygód. Jeśli potrzebujesz {passage}, daj znać.",
  ["data.otservbr.global.npc.captain.cookie.L65.994"] = "Do widzenia.",
  ["data.otservbr.global.npc.captain.cookie.L66.995"] = "Do widzenia.",
  ["data.otservbr.global.npc.captain.dreadnought.L433.1018"] = "No proszę, nowy",
  ["data.otservbr.global.npc.captain.dreadnought.L465.1019"] = "Na pewno chcesz marnować czas na tej skale? Mogę pokazać ci świat! Hę?",
  ["data.otservbr.global.npc.captain.fearless.L111.1155"] = "[PL] Welcome on board, |PLAYERNAME|. Where can I {sail} you today?",
  ["data.otservbr.global.npc.captain.fearless.L112.1156"] = "Do widzenia. Poleć nas, jeśli byłeś zadowolony z naszej obsługi.",
  ["data.otservbr.global.npc.captain.fearless.L113.1157"] = "W takim razie do widzenia.",
  ["data.otservbr.global.npc.captain.greyhound.L102.1514"] = "[PL] Welcome on board, |PLAYERNAME|. Where can I {sail} you today?",
  ["data.otservbr.global.npc.captain.greyhound.L103.1515"] = "Do widzenia. Poleć nas, jeśli byłeś zadowolony z naszej obsługi.",
  ["data.otservbr.global.npc.captain.greyhound.L104.1516"] = "W takim razie do widzenia.",
  ["data.otservbr.global.npc.captain.gulliver.L92.845"] = "Witamy na pokładzie, Sir |PLAYERNAME|. Dokąd mam cię dziś {sail}?",
  ["data.otservbr.global.npc.captain.gulliver.L93.846"] = "Do widzenia. Poleć nas, jeśli byłeś zadowolony z naszej obsługi.",
  ["data.otservbr.global.npc.captain.haba.L190.192"] = "Cześć.",
  ["data.otservbr.global.npc.captain.haba.L191.193"] = "Cześć.",
  ["data.otservbr.global.npc.captain.haba.L68.190"] = "Arrr, szczurze lądowy, czego chcesz? Pytasz o {passage}?",
  ["data.otservbr.global.npc.captain.haba.L70.191"] = "Arrr, szczurze lądowy, czego chcesz?",
  ["data.otservbr.global.npc.captain.haba.open.sea.L162.1353"] = "Na razie, szczurze lądowy!",
  ["data.otservbr.global.npc.captain.haba.open.sea.L176.1354"] = "Proszę bardzo! Użyj tego na dźwigu, gdy zobaczysz potwora. Potem uzupełniaj to za każdym razem, gdy użyjesz teleskopu.",
  ["data.otservbr.global.npc.captain.haba.open.sea.L58.1351"] = "Czego chcesz? Zapytaj mnie o {instructions}, jeśli nie wiesz, co robić! Jeśli chcesz wrócić do {Svargrond}, daj znać.",
  ["data.otservbr.global.npc.captain.haba.open.sea.L60.1352"] = "Znalazłeś miejsce |PLAYERNAME|!! Chwyć hełm głębin i udaj się tam na eksplorację {caves}.",
  ["data.otservbr.global.npc.captain.harava.L87.949"] = "Witamy na pokładzie, podróżniku. Dokąd mam cię dziś {sail}?",
  ["data.otservbr.global.npc.captain.harava.L88.950"] = "Do widzenia. Poleć nas, jeśli byłeś zadowolony z naszej obsługi.",
  ["data.otservbr.global.npc.captain.harava.L89.951"] = "W takim razie do widzenia.",
  ["data.otservbr.global.npc.captain.jack.rat.L57.982"] = "Witaj, piracie! Wskakuj na pokład, wracamy do domu! Witamy na statku Flying Bat. Mam stawiać {sail}s?",
  ["data.otservbr.global.npc.captain.jack.rat.L59.983"] = "(...)",
  ["data.otservbr.global.npc.captain.max.L85.659"] = "Ahoj, |PLAYERNAME|. Na jeden misja dla the badacz, eksplorator społeczeństwo, co?, nie??",
  ["data.otservbr.global.npc.captain.max.L86.660"] = "Do widzenia.",
  ["data.otservbr.global.npc.captain.max.L87.661"] = "Do widzenia.",
  ["data.otservbr.global.npc.captain.max.calassa.L68.1312"] = "Ahoj, |PLAYERNAME|. Na jeden misja dla the badacz, eksplorator społeczeństwo, co?, nie??",
  ["data.otservbr.global.npc.captain.max.calassa.L69.1313"] = "Do widzenia.",
  ["data.otservbr.global.npc.captain.max.calassa.L70.1314"] = "Do widzenia.",
  ["data.otservbr.global.npc.captain.pelagia.L102.862"] = "[PL] Welcome on board, |PLAYERNAME|. Where can I {sail} you today?",
  ["data.otservbr.global.npc.captain.pelagia.L103.863"] = "Do widzenia. Poleć nas, jeśli byłeś zadowolony z naszej obsługi.",
  ["data.otservbr.global.npc.captain.pelagia.L104.864"] = "W takim razie do widzenia.",
  ["data.otservbr.global.npc.captain.seagull.L105.1469"] = "[PL] Welcome on board, |PLAYERNAME|. Where can I {sail} you today?",
  ["data.otservbr.global.npc.captain.seagull.L106.1470"] = "Do widzenia. Poleć nas, jeśli byłeś zadowolony z naszej obsługi.",
  ["data.otservbr.global.npc.captain.seagull.L107.1471"] = "Do widzenia.",
  ["data.otservbr.global.npc.captain.seahorse.L86.1619"] = "[PL] Welcome on board, |PLAYERNAME|. Where may I {sail} you today?",
  ["data.otservbr.global.npc.captain.seahorse.L87.1620"] = "Do widzenia. Poleć nas, jeśli byłeś zadowolony z naszej obsługi.",
  ["data.otservbr.global.npc.captain.seahorse.L88.1621"] = "W takim razie do widzenia.",
  ["data.otservbr.global.npc.captain.sinbeard.L100.751"] = "W takim razie do widzenia.",
  ["data.otservbr.global.npc.captain.sinbeard.L98.749"] = "Witamy na pokładzie, Sir |PLAYERNAME|. Dokąd mam cię dziś {sail}?",
  ["data.otservbr.global.npc.captain.sinbeard.L99.750"] = "Do widzenia. Poleć nas, jeśli byłeś zadowolony z naszej obsługi.",
  ["data.otservbr.global.npc.captain.waverider.L97.707"] = "Pozdrowienia, śmiały poszukiwaczu przygód. Jeśli potrzebujesz {passage}, daj znać.",
  ["data.otservbr.global.npc.captain.waverider.L98.708"] = "Do widzenia.",
  ["data.otservbr.global.npc.captain.waverider.L99.709"] = "No cóż.",
  ["data.otservbr.global.npc.captain.waverider.island.L61.1025"] = "Pozdrowienia, śmiały poszukiwaczu przygód. Jeśli potrzebujesz powrotnego {passage}, daj znać.",
  ["data.otservbr.global.npc.captain.waverider.island.L62.1026"] = "Do widzenia.",
  ["data.otservbr.global.npc.captain.waverider.island.L63.1027"] = "No cóż.",
  ["data.otservbr.global.npc.caramellia.L100.981"] = "Witaj, |PLAYERNAME|. Proszę, zostaw mnie w spokoju w moim {mourning}.",
  ["data.otservbr.global.npc.carina.L97.831"] = "Witaj, |PLAYERNAME|. Chętnie z tobą pohandluję.",
  ["data.otservbr.global.npc.carlos.L100.1093"] = "Witaj z powrotem, |PLAYERNAME|, mam nadzieję, że zmieniłeś zdanie i przyniesiesz mi trochę {meat}? Dam ci za to złoto.",
  ["data.otservbr.global.npc.carlos.L103.1094"] = "Witaj z powrotem, |PLAYERNAME|! Udane polowanie i masz przy sobie kawałek {meat} albo szynki?",
  ["data.otservbr.global.npc.carlos.L107.1095"] = "Witaj z powrotem, Isleth Eagonst! Nadal masz ten kawałek mięsa albo szynki? Jeśli tak, poproś o {trade}, a dam ci trochę złota.",
  ["data.otservbr.global.npc.carlos.L110.1096"] = "Witaj z powrotem, |PLAYERNAME|! Gdzie podziałeś ten pyszny kawałek jedzenia? Sam go zjadłeś? No cóż, jeśli znajdziesz następny, wróć.",
  ["data.otservbr.global.npc.carlos.L115.1097"] = "Hej, |PLAYERNAME|! Właśnie tak działa handel z NPC-ami takimi jak ja. Myślę, że jesteś już gotów przejść przez most do wioski Rookgaard! Uważaj na siebie!",
  ["data.otservbr.global.npc.carlos.L121.1098"] = "Witaj ponownie, |PLAYERNAME|! Co ty tu jeszcze robisz? Powinieneś już iść przez most do wioski Rookgaard!",
  ["data.otservbr.global.npc.carlos.L241.1099"] = "Bardzo dobrze! Jedzenie dla mnie! Sprzedaj mi je, szybko! Gdy sprzedasz mi jedzenie, powiedz {ready}, żebym wiedział, że skończyłeś.",
  ["data.otservbr.global.npc.carlos.L242.1100"] = "Do widzenia, |PLAYERNAME|!",
  ["data.otservbr.global.npc.carlos.L243.1101"] = "Do widzenia, podróżniku, miłego pobytu na Rookgaard.",
  ["data.otservbr.global.npc.carlos.L86.1089"] = "Bądź pozdrowiony, |PLAYERNAME|! Jako krawiec i kupiec muszę powiedzieć - musimy coś zrobić z twoim {outfit}, prawda?",
  ["data.otservbr.global.npc.carlos.L91.1090"] = "Hej, myślałem, że uciekniesz, ale na szczęście wróciłeś. Pokażę ci, jak zmienić {outfit}, dobrze?",
  ["data.otservbr.global.npc.carlos.L94.1091"] = "Witaj z powrotem! Wiesz, po tej mojej małej usłudze z outfitami mam do ciebie drobną prośbę. Możesz mi {help}?",
  ["data.otservbr.global.npc.carlos.L97.1092"] = "O hej, |PLAYERNAME|, wciąż nie odpowiedziałeś na moje pytanie - mógłbyś pomóc mi zdobyć trochę {food}? Dam ci za to złoto.",
  ["data.otservbr.global.npc.cassino.L250.349"] = "Witaj w kasynie! Gramy tutaj w: \\n [WYPŁATA 180%] {HIGH / LOW}: High dla 4, 5, 6 i Low dla 1, 2 oraz 3 - {ODD / EVEN }: Odd dla 1, 3, 5 i Even dla 2, 4 oraz 6 \\n [WYPŁATA 500%] {NUMBERS}: Wybierasz liczbę, a jeśli trafisz ... {$$$$$}",
  ["data.otservbr.global.npc.cassino.L251.350"] = "Do widzenia.",
  ["data.otservbr.global.npc.cassino.L252.351"] = "Do widzenia.",
  ["data.otservbr.global.npc.cedrik.L148.1392"] = "Witaj, młody |PLAYERNAME|! Jeśli jesteś ciężko ranny lub zatruty, mogę cię za darmo {heal}.",
  ["data.otservbr.global.npc.cedrik.L149.1393"] = "Pamiętaj: jeśli jesteś ciężko ranny lub zatruty, mogę cię uleczyć za darmo.",
  ["data.otservbr.global.npc.cedrik.L150.1394"] = "Niech bogowie ci błogosławią, |PLAYERNAME|!",
  ["data.otservbr.global.npc.ceiron.L200.299"] = "Zawsze miło spotkać innego druida, |PLAYERNAME|.",
  ["data.otservbr.global.npc.ceiron.L201.300"] = "[PL] May Crunor bless and guide you, |PLAYERNAME|.",
  ["data.otservbr.global.npc.ceiron.L202.301"] = "[PL] May Crunor bless and guide you, |PLAYERNAME|.",
  ["data.otservbr.global.npc.cerdras.L85.657"] = "Pozdrowienia, mój przyjacielu!",
  ["data.otservbr.global.npc.cerdras.L86.658"] = "[PL] May Crunor bless and guide you, |PLAYERNAME|.",
  ["data.otservbr.global.npc.charles.L142.1490"] = "Ahoj. Dokąd mam cię dziś zabrać?",
  ["data.otservbr.global.npc.charles.L143.1491"] = "Cześć.",
  ["data.otservbr.global.npc.charles.L144.1492"] = "Cześć.",
  ["data.otservbr.global.npc.charlotta.L85.901"] = "Ach, witaj! Witaj |PLAYERNAME|! Jeśli potrzebujesz druidzkich zaklęć, dobrze trafiłeś. A poza tym zawsze miło mieć gościa.",
  ["data.otservbr.global.npc.charlotta.L86.902"] = "Do widzenia.",
  ["data.otservbr.global.npc.charlotta.L87.903"] = "No cóż.",
  ["data.otservbr.global.npc.chartan.L107.1622"] = "Wielki Znake wybacz mi, że rozmawiam z tym niegodnym blankskinem.",
  ["data.otservbr.global.npc.chavis.L118.1346"] = "Hej! Nie masz przypadkiem trochę {food}, którym chciałbyś się podzielić? No gdzie moje maniery, najpierw serdeczne powitanie.",
  ["data.otservbr.global.npc.chavis.L119.1347"] = "Uważaj tam na zewnątrz!",
  ["data.otservbr.global.npc.chemar.L87.743"] = "Błogosławieństwo Daramana, podróżniku |PLAYERNAME|.",
  ["data.otservbr.global.npc.chemar.L89.744"] = "To była przyjemność ci pomóc, |PLAYERNAME|.",
  ["data.otservbr.global.npc.chemar.L90.745"] = "To była przyjemność ci pomóc, |PLAYERNAME|.",
  ["data.otservbr.global.npc.chester.kahs.L304.472"] = "Pozdrowienia, nieznajomy.",
  ["data.otservbr.global.npc.chester.kahs.L305.473"] = "Uważaj tam na zewnątrz!",
  ["data.otservbr.global.npc.chester.kahs.L306.474"] = "Uważaj tam na zewnątrz!",
  ["data.otservbr.global.npc.chief.grarkharok.L158.1407"] = "[PL] Me Chief Grarkharok! No do {nothing}!",
  ["data.otservbr.global.npc.chief.grarkharok.L159.1408"] = "Grarkharok to {chief}!",
  ["data.otservbr.global.npc.chief.grarkharok.L160.1409"] = "Grarkharok to {chief}!",
  ["data.otservbr.global.npc.chondur.L319.194"] = "Bądź pozdrowione, dziecko.",
  ["data.otservbr.global.npc.chondur.L320.195"] = "Do widzenia.",
  ["data.otservbr.global.npc.chrak.L93.1133"] = "Pozdrowionka, zawodniku.",
  ["data.otservbr.global.npc.chrystal.L77.787"] = "Do usług, |PLAYERNAME|, witaj na poczcie.",
  ["data.otservbr.global.npc.chrystal.L78.788"] = "Kto następny?",
  ["data.otservbr.global.npc.chrystal.L79.789"] = "Kto następny?",
  ["data.otservbr.global.npc.chrystal.L80.790"] = "Proszę. Nie zapomnij, że jeśli chcesz wysłać paczkę, musisz też kupić etykietę. Zawsze wpisuj imię {receiver} w pierwszej linii.",
  ["data.otservbr.global.npc.chuckles.L148.1321"] = "Oczywiście, przejrzyj moje towary. A może chcesz zobaczyć tylko",
  ["data.otservbr.global.npc.cipfried.L176.714"] = "No to cześć.",
  ["data.otservbr.global.npc.cipfried.L177.715"] = "Żegnaj, |PLAYERNAME|!",
  ["data.otservbr.global.npc.cipfried.L64.712"] = "Witaj, |PLAYERNAME|! Wyglądasz naprawdę kiepsko. Pozwól, że uleczę twoje rany. To przecież moja praca.",
  ["data.otservbr.global.npc.cipfried.L73.713"] = "[PL] Hello, |PLAYERNAME|! I'll {heal} you if you are injured or poisoned. Feel free to ask me for {help} or general {hints}.",
  ["data.otservbr.global.npc.cledwyn.L212.1118"] = "Błogosławieństwa, Gracz! Jak mogę służyć? Czy chcesz wymienić kilka {token}, czy też {information} lub {talk}? Czy powinienem {enchant} dla Ciebie pewne przedmioty?",
  ["data.otservbr.global.npc.cobra.L53.1172"] = "Krocz ścieżką rozkładu!",
  ["data.otservbr.global.npc.coltrayne.L118.1241"] = "Hej. Potrzebujesz pancerza albo broni? To zapytaj o {trade}.",
  ["data.otservbr.global.npc.coltrayne.L119.1242"] = "Ta, pa..",
  ["data.otservbr.global.npc.commander.stone.L232.80"] = "Witaj, rekrucie.",
  ["data.otservbr.global.npc.cornelia.L93.932"] = "Witaj w najlepszym sklepie z {armor} w tej krainie, |PLAYERNAME|!",
  ["data.otservbr.global.npc.cornelia.L94.933"] = "Do widzenia. Wróć wkrótce.",
  ["data.otservbr.global.npc.cornell.L73.81"] = "[PL] Welcome on board, |PLAYERNAME|. Where can I {sail} you today, to {Grimvale} or {Edron}?",
  ["data.otservbr.global.npc.cornell.L74.82"] = "Do widzenia. Poleć nas, jeśli byłeś zadowolony z naszej obsługi.",
  ["data.otservbr.global.npc.cornell.L75.83"] = "W takim razie do widzenia.",
  ["data.otservbr.global.npc.corym.butler.L62.1150"] = "Musimy wydobywać cenne surowce, ale nie mamy dość jedzenia. Sytuacja jest tragiczna.",
  ["data.otservbr.global.npc.corym.butler.L87.1151"] = "Do widzenia, |PLAYERNAME|.",
  ["data.otservbr.global.npc.corym.footman.L62.228"] = "To, co jemy, jest naprawdę śmieszne.",
  ["data.otservbr.global.npc.corym.footman.L87.229"] = "Do widzenia, |PLAYERNAME|.",
  ["data.otservbr.global.npc.corym.ratter.L63.1029"] = "Wydobywamy wszystko, co matka ziemia nam daje, cenne zasoby naturalne.",
  ["data.otservbr.global.npc.corym.ratter.L92.1030"] = "Do widzenia, |PLAYERNAME|.",
  ["data.otservbr.global.npc.corym.servant.L127.549"] = "Do widzenia, |PLAYERNAME|.",
  ["data.otservbr.global.npc.corym.servant.L76.548"] = "Każdy człowiek jest kowalem własnego losu. Czasy ucisku wreszcie się skończyły.",
  ["data.otservbr.global.npc.corym.slave.L62.665"] = "Ucisk trwał zbyt długo. Z naszą nową bronią winni ludzie dostaną zasłużoną karę.",
  ["data.otservbr.global.npc.corym.slave.L87.666"] = "Do widzenia, |PLAYERNAME|.",
  ["data.otservbr.global.npc.corym.worker.01.L65.1136"] = "Mój bohaterze! Mój znajomy wysłał cię, żeby mnie uwolnić? To prawdziwy przyjaciel!",
  ["data.otservbr.global.npc.corym.worker.01.L80.1137"] = "Do widzenia, |PLAYERNAME|.",
  ["data.otservbr.global.npc.corym.worker.02.L62.1558"] = "Potrzebujemy broni, by poprawić naszą sytuację.",
  ["data.otservbr.global.npc.corym.worker.02.L87.1559"] = "Do widzenia, |PLAYERNAME|.",
  ["data.otservbr.global.npc.corym.worker.03.L65.1"] = "Mój bohaterze! Mój znajomy wysłał cię, żeby mnie uwolnić? To prawdziwy przyjaciel!",
  ["data.otservbr.global.npc.corym.worker.03.L79.2"] = "Do widzenia, |PLAYERNAME|.",
  ["data.otservbr.global.npc.corym.worker.04.L64.507"] = "Każdy człowiek jest kowalem własnego losu. Chcę znów ujrzeć światło dnia! Po prostu poczuć świeże powietrze.",
