  ["data.otservbr.global.npc.hireling.L793.1382"] = "Żegnaj, |PLAYERNAME|, będę tu, jeśli znów będziesz mnie potrzebować.",
  ["data.otservbr.global.npc.hireling.L794.1383"] = "Wróć wkrótce!",
  ["data.otservbr.global.npc.hjaern.L234.1020"] = "Witaj, |PLAYERNAME|. Świat {spiritual} patrzy na ciebie i twoje czyny.",
  ["data.otservbr.global.npc.hoggle.L59.1549"] = "Witaj w moim skromnym domu!",
  ["data.otservbr.global.npc.hoggle.L60.1550"] = "Do widzenia.",
  ["data.otservbr.global.npc.hoggle.L61.1551"] = "Do widzenia.",
  ["data.otservbr.global.npc.humgolf.L92.710"] = "|PLAYERNAME|, dzień dobry... albo noc dobry... cokolwiek.",
  ["data.otservbr.global.npc.humphrey.L111.77"] = "Witaj, szlachetny |PLAYERNAME|",
  ["data.otservbr.global.npc.humphrey.L112.78"] = "Do widzenia, szlachetny |PLAYERNAME|",
  ["data.otservbr.global.npc.humphrey.L113.79"] = "Do widzenia, szlachetny |PLAYERNAME|",
  ["data.otservbr.global.npc.huntsman.L101.381"] = "Do widzenia. Uważaj na siebie.",
  ["data.otservbr.global.npc.huntsman.L102.382"] = "Wciąż cię widzę.",
  ["data.otservbr.global.npc.huntsman.L103.383"] = "No witaj, partnerze.",
  ["data.otservbr.global.npc.hyacinth.L219.654"] = "Niech Crunor ci błogosławi.",
  ["data.otservbr.global.npc.hyacinth.L220.655"] = "Niech Crunor ci błogosławi.",
  ["data.otservbr.global.npc.hyacinth.L221.656"] = "Proszę. Nie zapomnij, jeśli kupujesz mikstury, za pustą fiolkę jest {deposit} 5 sztuk złota.",
  ["data.otservbr.global.npc.hyacinth.L58.651"] = "Pozdrawiam, podróżniku |PLAYERNAME|. To ty musisz być tym, którego przysłała Lily. Czy masz dla mnie worek {herbs}?",
  ["data.otservbr.global.npc.hyacinth.L60.652"] = "Pozdrowienia, podróżniku |PLAYERNAME|. Wciąż mam dla ciebie prezent! Chcesz go teraz?",
  ["data.otservbr.global.npc.hyacinth.L62.653"] = "Pozdrowienia, podróżniku |PLAYERNAME|. Skoro odnalazłeś drogę do mojej chaty, jak mogę ci {help}?",
  ["data.otservbr.global.npc.ikassis.L94.1288"] = "Błogosławieństwo natury, podróżniku!",
  ["data.otservbr.global.npc.imalas.L55.670"] = "Witaj |PLAYERNAME|! Czego potrzebujesz? Jeśli chodzi o {food}, trafiłeś we właściwe miejsce.",
  ["data.otservbr.global.npc.imalas.L56.671"] = "Jasne, dobrze się rozejrzyj.",
  ["data.otservbr.global.npc.imbuement.assistant.L359.557"] = "[PL] Hello |PLAYERNAME|, say {imbuement packages} or {trade} for buy imbuement items.",
  ["data.otservbr.global.npc.imbuement.assistant.L360.558"] = "Do zobaczenia później, |PLAYERNAME|, wróć wkrótce.",
  ["data.otservbr.global.npc.imbuement.assistant.L361.559"] = "Do zobaczenia później, |PLAYERNAME|, wróć wkrótce.",
  ["data.otservbr.global.npc.iptar.sin.L184.984"] = "[PL] Welcome, young |PLAYERNAME|! If you are heavily wounded or poisoned, I can {heal} you for free or you want the {adventurer stone}?",
  ["data.otservbr.global.npc.iptar.sin.L185.985"] = "Pamiętaj: jeśli jesteś ciężko ranny lub zatruty, mogę cię uleczyć za darmo.",
  ["data.otservbr.global.npc.iptar.sin.L186.986"] = "Niech bogowie ci błogosławią, |PLAYERNAME|!",
  ["data.otservbr.global.npc.irea.L53.184"] = "Do widzenia!",
  ["data.otservbr.global.npc.irmana.L275.380"] = "Witaj w domu mody, |PLAYERNAME|!",
  ["data.otservbr.global.npc.ishebad.L53.1162"] = "Niech żałoba ci towarzyszy, pielgrzymie w ciele. Szukasz promocji?",
  ["data.otservbr.global.npc.ishebad.L54.1163"] = "Do widzenia, |PLAYERNAME|!",
  ["data.otservbr.global.npc.ishebad.L55.1164"] = "Do widzenia, |PLAYERNAME|!",
  ["data.otservbr.global.npc.ishina.L111.412"] = "[PL] Be greeted, |PLAYERNAME|. Which of my fine gems do you {need}?",
  ["data.otservbr.global.npc.ishina.L112.413"] = "Błogosławieństwo Daramana i do widzenia.",
  ["data.otservbr.global.npc.ishina.L113.414"] = "Błogosławieństwo Daramana i do widzenia.",
  ["data.otservbr.global.npc.isimov.L169.1003"] = "Witaj, młody |PLAYERNAME|! Jeśli jesteś ciężko ranny lub zatruty, mogę cię za darmo {heal}.",
  ["data.otservbr.global.npc.isimov.L170.1004"] = "Pamiętaj: jeśli jesteś ciężko ranny lub zatruty, mogę cię uleczyć za darmo.",
  ["data.otservbr.global.npc.isimov.L171.1005"] = "Niech bogowie ci błogosławią, |PLAYERNAME|!",
  ["data.otservbr.global.npc.iskan.L55.1279"] = "Nie jesteś jednym z nas. Nie chcę z tobą rozmawiać.",
  ["data.otservbr.global.npc.iskan.L57.1280"] = "Powiedziano mi, że zabijałeś husky tutaj, w Svargrond! Nigdy więcej tego nie rób, dobrze? To dla nas cenne zwierzęta. Daj mi 500 sztuk złota, a zapomnę o tym incydencie i nic nie powiem Jarlowi Svenowi. Zgoda?",
  ["data.otservbr.global.npc.iskan.L59.1281"] = "CHWAŁA Wodzowi Areny! |PLAYERNAME|, Bohaterze Svargrond! Co mogę dla ciebie {do for you}?",
  ["data.otservbr.global.npc.iskan.L61.1282"] = "Pozdrowienia. Co mogę dla ciebie {do for you}?",
  ["data.otservbr.global.npc.ivalisse.L124.1119"] = "Witaj, wyznawco Astral Shapers! Witaj w świątyni! Skoro jesteś tu, by złożyć hołd, możesz też dowiedzieć się czegoś o pradawnej sztuce imbuingu.",
  ["data.otservbr.global.npc.ivalisse.L125.1120"] = "Och... żegnaj, dziecko.",
  ["data.otservbr.global.npc.iwan.L59.1266"] = "Czuj się jak u siebie w moim sklepie z klejnotami, |PLAYERNAME|.",
  ["data.otservbr.global.npc.iwan.L60.1267"] = "Pa, pa.",
  ["data.otservbr.global.npc.iwan.L61.1268"] = "Pa, pa.",
  ["data.otservbr.global.npc.iwan.L62.1269"] = "Proszę, spójrz.",
  ["data.otservbr.global.npc.iwar.L84.274"] = "Hej ho, Pogromco Burz! Witaj w sklepie meblowym Kazordoon.",
  ["data.otservbr.global.npc.iwar.L85.275"] = "No to cześć.",
  ["data.otservbr.global.npc.iyad.L107.746"] = "Wreszcie! K...k...klient! G...gdzie chcesz, żebym cię z...z...{fly}?",
  ["data.otservbr.global.npc.iyad.L108.747"] = "B...błogosławieństwo Daramana... och, jak tęsknię za c...ciepłą Darashią...",
  ["data.otservbr.global.npc.iyad.L109.748"] = "Do widzenia!",
  ["data.otservbr.global.npc.izsh.L81.1012"] = "Pozdrowionka, łuskowata istoto.",
  ["data.otservbr.global.npc.jack.L67.1251"] = "Ty!! Co powiedziałeś mojej rodzinie? Są na mnie źli, a ja nawet nie wiem dlaczego! Myślą, że ich okłamałem, mówiąc o tajnej pracy w Edron! Po co miałbym to robić!",
  ["data.otservbr.global.npc.jack.L75.1252"] = "Więc wróciłeś od Spectulusa? Co powiedział, czy coś jest nie tak? Masz ten dziwny wyraz twarzy - czy coś jest nie tak? Powiedziałeś mi tu prawdę, prawda?",
  ["data.otservbr.global.npc.jack.L77.1253"] = "Tak? Co mogę dla ciebie zrobić? Mam nadzieję, że to nie potrwa długo.",
  ["data.otservbr.global.npc.jack.drone.L61.504"] = "Witaj na pokładzie, |PLAYERNAME|. Dokąd mam cię dziś {sail}? Mogę zabrać cię z powrotem do {thais}.",
  ["data.otservbr.global.npc.jack.drone.L62.505"] = "Do widzenia. Poleć nas, jeśli byłeś zadowolony z naszej obsługi.",
  ["data.otservbr.global.npc.jack.drone.L63.506"] = "W takim razie do widzenia.",
  ["data.otservbr.global.npc.jack.fate.L109.733"] = "Witamy na pokładzie, Sir |PLAYERNAME|.",
  ["data.otservbr.global.npc.jack.fate.L110.734"] = "Do widzenia. Poleć nas, jeśli byłeś zadowolony z naszej obsługi.",
  ["data.otservbr.global.npc.jack.fate.L111.735"] = "W takim razie do widzenia.",
  ["data.otservbr.global.npc.jack.fate.goroma.L116.306"] = "[PL] Hello, Sir |PLAYERNAME|. Where can I {sail} you today?",
  ["data.otservbr.global.npc.jack.fate.goroma.L117.307"] = "Do widzenia.",
  ["data.otservbr.global.npc.jack.fate.goroma.L118.308"] = "W takim razie do widzenia.",
  ["data.otservbr.global.npc.jack.springer.L202.393"] = "Oczywiście, mój przyjacielu.",
  ["data.otservbr.global.npc.jack.springer.L83.389"] = "[PL] Welcome, |PLAYERNAME|! There is much we have to {discuss}.",
  ["data.otservbr.global.npc.jack.springer.L85.390"] = "Witaj, nieznajomy! Wyglądasz mi podejrzanie. Nie sądzę, żebyśmy mieli o czym rozmawiać.",
  ["data.otservbr.global.npc.jack.springer.L87.391"] = "[PL] Welcome, |PLAYERNAME|! Is there anything to {report}?",
  ["data.otservbr.global.npc.jack.springer.L90.392"] = "Witaj, nieznajomy! Wybacz, ale nigdy o tobie nie słyszałem. Szukam bardziej doświadczonej pomocy.",
  ["data.otservbr.global.npc.jacob.L132.763"] = "<kiwa głową> Cześć.",
  ["data.otservbr.global.npc.jacob.L133.764"] = "<kiwa głową> Na razie.",
  ["data.otservbr.global.npc.jakahr.L53.433"] = "Witaj, pogrążony w żałobie pielgrzymie. Jak mogę ci pomóc, |PLAYERNAME|?",
  ["data.otservbr.global.npc.jakahr.L54.434"] = "To był zaszczyt ci służyć, |PLAYERNAME|.",
  ["data.otservbr.global.npc.jakahr.L55.435"] = "To był zaszczyt ci służyć.",
  ["data.otservbr.global.npc.jakahr.L56.436"] = "Proszę. Nie zapomnij, że jeśli chcesz wysłać paczkę, musisz też kupić etykietę. Zawsze wpisuj imię {receiver} w pierwszej linii.",
  ["data.otservbr.global.npc.jamesfrancis.L116.650"] = "No to cześć.",
  ["data.otservbr.global.npc.jamesfrancis.L64.648"] = "Gerimor ma rację. Jako ekspert od minotaurów badam te stworzenia od lat. Myślałem, że wiem już wiele, ale potwory w tej jaskini są {different}. To wielka {mystery}.",
  ["data.otservbr.global.npc.jamesfrancis.L67.649"] = "Jak idzie twoja {mission}?",
  ["data.otservbr.global.npc.jean.pierre.L116.691"] = "Pozdrowienia, |PLAYERNAME|. Co tu robisz?",
  ["data.otservbr.global.npc.jefrey.L76.522"] = "Tak? Co mogę dla ciebie zrobić, |PLAYERNAME|? Może sprawy bankowe?",
  ["data.otservbr.global.npc.jefrey.L77.523"] = "Miłego dnia.",
  ["data.otservbr.global.npc.jefrey.L78.524"] = "Miłego dnia.",
  ["data.otservbr.global.npc.jerom.L132.946"] = "Cześć.",
  ["data.otservbr.global.npc.jerom.L133.947"] = "Cześć.",
  ["data.otservbr.global.npc.jerom.L134.948"] = "Witaj. Wybacz, ale dziś nie jestem w najlepszym {mood}.",
  ["data.otservbr.global.npc.jessica.L76.1594"] = "Tak? Co mogę dla ciebie zrobić, |PLAYERNAME|? Może sprawy bankowe?",
  ["data.otservbr.global.npc.jessica.L77.1595"] = "Miłego dnia.",
  ["data.otservbr.global.npc.jessica.L78.1596"] = "Miłego dnia.",
  ["data.otservbr.global.npc.jezzara.L59.1141"] = "Niech żałoba ci towarzyszy, pielgrzymie w ciele. Skoro mowa o ciele, może masz ochotę na {food}?",
  ["data.otservbr.global.npc.jezzara.L60.1142"] = "Niech oświecenie prowadzi twoją drogę.",
  ["data.otservbr.global.npc.jezzara.L61.1143"] = "Niech oświecenie prowadzi twoją drogę.",
  ["data.otservbr.global.npc.jezzara.L62.1144"] = "Jasne, spójrz na moje oferty.",
  ["data.otservbr.global.npc.jondrin.L76.1431"] = "Cześć!",
  ["data.otservbr.global.npc.julius.L255.639"] = "Do widzenia, |PLAYERNAME|. Nigdy nikomu nie ufaj.",
  ["data.otservbr.global.npc.julius.L256.640"] = "Wynagrodzę cię za każdą parę wampirzych kłów, które mi przyniesiesz.",
  ["data.otservbr.global.npc.julius.L58.637"] = "Witaj, poszukiwaczu przygód |PLAYERNAME|. Zakładam, że przeczytałeś {note} o zagrożeniu {vampire} w tym mieście.",
  ["data.otservbr.global.npc.julius.L60.638"] = "Witaj, poszukiwaczu przygód |PLAYERNAME|. Wybacz, jeśli wyglądam na {distracted}!",
  ["data.otservbr.global.npc.junkar.mines.L68.1372"] = "Witaj, |PLAYERNAME|! Masz szczęście, że usługa działa właśnie teraz. Oszczędzaj jednak swój węgiel na kolejne dni!",
