  ["data.otservbr.global.npc.kais.L104.736"] = "Hmm... z pewnością potrzebujesz {help} - pozwolisz mi? Jestem {Kais} the Bound i mogę pomóc ci w {healing} ciała i duszy, a nawet dać {enhanced} błogosławieństwo!",
  ["data.otservbr.global.npc.kais.L105.737"] = "Żegnaj... |PLAYERNAME|",
