  ["data.otservbr.global.npc.lardoc.bashsmite.L259.1202"] = "Skoro najwyraźniej nie jesteś jednym z moich krewnych, którzy składają mi od dawna zaległą wizytę, powinniśmy od razu zabrać się do {work}. Zobaczymy, czy potrafisz udowodnić swoją {worth} dla naszego sojuszu.",
  ["data.otservbr.global.npc.lardoc.bashsmite.L260.1203"] = "No to cześć.",
  ["data.otservbr.global.npc.lavirias.L57.36"] = "Do widzenia!",
  ["data.otservbr.global.npc.lazaran.L176.388"] = "Ja witać. Ty nie wróg plemienia.",
  ["data.otservbr.global.npc.lea.L61.1368"] = "Pozdrowienia, |PLAYERNAME|.",
  ["data.otservbr.global.npc.lea.L62.1369"] = "Uważaj w podróży.",
  ["data.otservbr.global.npc.lector.L55.1218"] = "[PL] Welcome to my humble {meat} shop, |PLAYERNAME|.",
  ["data.otservbr.global.npc.lector.L56.1219"] = "Proszę, wpadnij i kup ponownie, |PLAYERNAME|.",
  ["data.otservbr.global.npc.lector.L57.1220"] = "Oczywiście, dobrze przyjrzyj się mojemu mięsu.",
  ["data.otservbr.global.npc.lee.delle.L150.408"] = "Pa, pa.",
  ["data.otservbr.global.npc.lee.delle.L151.409"] = "Pa, pa, |PLAYERNAME|.",
  ["data.otservbr.global.npc.lee.delle.L152.410"] = "Jasne, spójrz sobie, kochanie.",
  ["data.otservbr.global.npc.lee.delle.L153.411"] = "Miło cię widzieć, |PLAYERNAME|! Poproś o {trade}, jeśli chcesz zobaczyć moje wyjątkowe oferty.",
  ["data.otservbr.global.npc.liane.L95.484"] = "Cześć. Jak mogę Ci pomóc |PLAYERNAME|? Jeśli chcesz coś kupić, zapytaj mnie o wymianę. Mogę również wyjaśnić system {mail}.",
  ["data.otservbr.global.npc.liane.L96.485"] = "To była przyjemność ci pomóc, |PLAYERNAME|.",
  ["data.otservbr.global.npc.liane.L97.486"] = "To była przyjemność ci pomóc, |PLAYERNAME|.",
  ["data.otservbr.global.npc.liane.L98.487"] = "Proszę. Nie zapomnij, że jeśli chcesz wysłać paczkę, musisz też kupić etykietę. Zawsze wpisuj imię {receiver} w pierwszej linii.",
  ["data.otservbr.global.npc.lily.L283.121"] = "Niech Crunor ci błogosławi!",
  ["data.otservbr.global.npc.lily.L284.122"] = "Uważaj, |PLAYERNAME|.",
  ["data.otservbr.global.npc.lily.L285.123"] = "Oczywiście, przejrzyj moje oferty. Jeśli kupujesz miksturę, pamiętaj, że za pustą fiolkę jest {deposit} 5 sztuk złota.",
  ["data.otservbr.global.npc.lily.L69.118"] = "Hej, |PLAYERNAME|! Vascalir musiał cię przysłać, żebyś pomógł mi w małej {mission}, prawda?",
  ["data.otservbr.global.npc.lily.L72.119"] = "Witaj, |PLAYERNAME|! Tak szybko wróciłeś? Dostarczyłeś zioła do Hyacinth?",
  ["data.otservbr.global.npc.lily.L74.120"] = "Witaj, |PLAYERNAME|! Wyglądasz dziś na trochę zestresowanego. Jeśli chcesz zobaczyć moje oferty mikstur, poproś o {trade}. Jeśli szukasz marketu i lochów, idź ścieżką na wschód!",
  ["data.otservbr.global.npc.lisander.L77.251"] = "Wolałbym, żeby mi nie przeszkadzać i zostawić mnie w {peace}. Mów krótko.",
  ["data.otservbr.global.npc.llathriel.L53.1322"] = "Do widzenia!",
  ["data.otservbr.global.npc.lokur.L110.616"] = "Tak? Co mogę dla ciebie zrobić, |PLAYERNAME|? Może sprawy bankowe?",
  ["data.otservbr.global.npc.lokur.L111.617"] = "Miłego dnia.",
  ["data.otservbr.global.npc.lokur.L112.618"] = "Miłego dnia.",
  ["data.otservbr.global.npc.lorbas.L93.1556"] = "Witaj, drogi podróżniku.",
  ["data.otservbr.global.npc.lorietta.L148.1077"] = "Witaj, młody |PLAYERNAME|! Jeśli jesteś ciężko ranny lub zatruty, mogę cię za darmo {heal}.",
  ["data.otservbr.global.npc.lorietta.L149.1078"] = "Pamiętaj: jeśli jesteś ciężko ranny lub zatruty, mogę cię uleczyć za darmo.",
  ["data.otservbr.global.npc.lorietta.L150.1079"] = "Niech bogowie ci błogosławią, |PLAYERNAME|!",
  ["data.otservbr.global.npc.lothar.L129.304"] = "Witaj w mojej skromnej chacie, |PLAYERNAME|. Co cię tu {here}?",
  ["data.otservbr.global.npc.lothar.L130.305"] = "Dbaj o siebie.",
  ["data.otservbr.global.npc.loui.L105.1165"] = "TRZYMAJ SIĘ Z DALEKA OD TEJ DZIURY!",
  ["data.otservbr.global.npc.loui.L106.1166"] = "Niech bogowie cię chronią! I trzymaj się z dala od tej dziury!",
  ["data.otservbr.global.npc.loui.L107.1167"] = "UWAGA! Uważaj na tę {hole}!",
  ["data.otservbr.global.npc.lubo.L156.1432"] = "Witaj w moim sklepie dla poszukiwaczy przygód, |PLAYERNAME|! Czego potrzebujesz? Poproś o {trade}, by obejrzeć mój towar.",
  ["data.otservbr.global.npc.lubo.L157.1433"] = "Do widzenia, |PLAYERNAME|.",
  ["data.otservbr.global.npc.lubo.L158.1434"] = "Do widzenia.",
  ["data.otservbr.global.npc.lugri.L203.8"] = "Czego {want}, |PLAYERNAME|?",
  ["data.otservbr.global.npc.lugri.L204.9"] = "Cześć.",
  ["data.otservbr.global.npc.lugri.L205.10"] = "Cześć.",
  ["data.otservbr.global.npc.lukosch.L87.215"] = "Witaj, |PLAYERNAME|! Czujesz zew przygody? Chcesz tygodniowy {ticket} na tutejszy system wagoników górniczych? Możesz go użyć od razu, by dostać się do centrum Kazordoon!",
  ["data.otservbr.global.npc.lukosch.L88.216"] = "Mam nadzieję, że znów cię zobaczę.",
  ["data.otservbr.global.npc.luna.L61.1332"] = "Pozdrowienia, podróżniku. Może chcesz rzucić okiem na moje {offers}...",
  ["data.otservbr.global.npc.luna.L62.1333"] = "Żegnaj, podróżniku.",
  ["data.otservbr.global.npc.luna.L63.1334"] = "Żegnaj, podróżniku.",
  ["data.otservbr.global.npc.luna.L64.1335"] = "Oczywiście, przejrzyj moje towary.",
  ["data.otservbr.global.npc.lurik.L153.1502"] = "[PL] Welcome to the {explorer society} headquarter of Svargrond, |PLAYERNAME|!",
  ["data.otservbr.global.npc.lynda.L307.1507"] = "Witaj w imieniu bogów, pielgrzymie |PLAYERNAME|!",
  ["data.otservbr.global.npc.lynda.L308.1508"] = "Uważaj w podróży.",
  ["data.otservbr.global.npc.lynda.L309.1509"] = "Uważaj w podróży.",
  ["data.otservbr.global.npc.maealil.L170.1601"] = "Witaj, młody |PLAYERNAME|! Jeśli jesteś ciężko ranny lub zatruty, mogę cię za darmo {heal}.",
