  ["data.otservbr.global.npc.maealil.L172.1603"] = "Niech bogowie ci błogosławią, |PLAYERNAME|!",
  ["data.otservbr.global.npc.maelyrra.L176.895"] = "Błogosławieństwo natury! Witaj w krainie snów.",
  ["data.otservbr.global.npc.maelyrra.L177.896"] = "Niech twoja droga zawsze będzie równa.",
  ["data.otservbr.global.npc.maelyrra.L178.897"] = "Niech twoja droga zawsze będzie równa.",
  ["data.otservbr.global.npc.maeryn.L178.1255"] = "Pozdrowienia, przybyszu. Ciekawe, co sprowadza cię do tego {dangerous} miejsca.",
  ["data.otservbr.global.npc.malor.L193.131"] = "Żegnaj, człowieku. Kiedy zajmę należne mi miejsce, zapamiętam tych, którzy dobrze mi służyli. Nawet jeśli to tylko ludzie.",
  ["data.otservbr.global.npc.malor.L194.132"] = "Żegnaj, człowieku.",
  ["data.otservbr.global.npc.malunga.L58.1370"] = "Pozdrowienia. Mam mało czasu do {spare}, więc rozmowa będzie krótka. Uczę czarodziei {spells} i kupuję trochę magicznych {ingredients}.",
  ["data.otservbr.global.npc.marina.L128.1472"] = "Och, witaj |PLAYERNAME|. Gość, jak miło!",
  ["data.otservbr.global.npc.maris.L91.978"] = "Mam nadzieję, że masz dobry powód, by zbliżać się do mojego {ship}, |PLAYERNAME|.",
  ["data.otservbr.global.npc.maris.L92.979"] = "Ta, pa czy coś.",
  ["data.otservbr.global.npc.maris.L93.980"] = "Cześć.",
  ["data.otservbr.global.npc.maris.fenrock.L72.111"] = "Och, wciąż żyjesz. Witaj, |PLAYERNAME|.",
  ["data.otservbr.global.npc.maris.fenrock.L73.112"] = "Ta, pa czy coś.",
  ["data.otservbr.global.npc.maris.fenrock.L74.113"] = "Cześć.",
  ["data.otservbr.global.npc.maris.mistrock.L89.667"] = "Och, wciąż żyjesz. Witaj, |PLAYERNAME|.",
  ["data.otservbr.global.npc.maris.mistrock.L90.668"] = "Ta, pa czy coś.",
  ["data.otservbr.global.npc.maris.mistrock.L91.669"] = "Cześć.",
  ["data.otservbr.global.npc.markwin.L59.904"] = "Intruz! Straże, brać go!",
  ["data.otservbr.global.npc.markwin.L72.905"] = "No cóż... pokonałeś moich strażników! Teraz wszystko stracone! Chyba będę musiał odpowiedzieć na twoje pytania.",
  ["data.otservbr.global.npc.markwin.L75.906"] = "Och, znowu ty. Czego chcesz, bezrogi posłańcu?",
  ["data.otservbr.global.npc.marlene.L100.422"] = "Ach, witaj |PLAYERNAME|! Powiedz, czy słyszałeś już najnowsze wiadomości o {seamonster}, {Aneus} lub {rumours} w tym obszarze?",
  ["data.otservbr.global.npc.marlene.L101.423"] = "Do widzenia i wpadaj znów na krótką pogawędkę! *macha*",
  ["data.otservbr.global.npc.marvin.L92.130"] = "Ach, przychodzisz akurat na specjalne głosowanie dotyczące najnowszego projektu {funding}. Domyślam się, że chcesz wziąć w nim udział.",
  ["data.otservbr.global.npc.maryza.L108.396"] = "Do widzenia!",
  ["data.otservbr.global.npc.mazarius.L189.562"] = "Pozdrowienia, drogi gościu. Powiedz proszę, co cię tu {brings}, do mojego skromnego domu.",
  ["data.otservbr.global.npc.mazarius.L190.563"] = "Do widzenia.",
  ["data.otservbr.global.npc.mazarius.L191.564"] = "No cóż.",
  ["data.otservbr.global.npc.mehkesh.L59.619"] = "Niech żałoba ci towarzyszy, |PLAYERNAME|, pielgrzymie w ciele. Jeśli szukasz mikstur, nie musisz szukać dalej.",
