  ["data.otservbr.global.npc.mehkesh.L61.621"] = "Niech oświecenie prowadzi twoją drogę, |PLAYERNAME|.",
  ["data.otservbr.global.npc.mehkesh.L62.622"] = "Jasne.",
  ["data.otservbr.global.npc.melchior.L86.1116"] = "Żegnaj, nieznajomy. Niech mądry Uman prowadzi twoje kroki po tej zdradliwej krainie.",
  ["data.otservbr.global.npc.melchior.L87.1117"] = "Żegnaj, nieznajomy. Niech mądry Uman prowadzi twoje kroki po tej zdradliwej krainie.",
  ["data.otservbr.global.npc.melfar.L135.692"] = "Po prostu świetnie, kolejne zakłócenie. Tego właśnie mi trzeba.",
  ["data.otservbr.global.npc.melian.L94.776"] = "Pozdrowienia, podróżniku |PLAYERNAME|. Dokąd chcesz, żebym cię {fly}?",
  ["data.otservbr.global.npc.melian.L95.777"] = "Do widzenia!",
  ["data.otservbr.global.npc.melian.L96.778"] = "Do widzenia!",
  ["data.otservbr.global.npc.memech.L59.1193"] = "Niech żałoba ci towarzyszy, |PLAYERNAME|, pielgrzymie w ciele. Rzuć okiem na moją wspaniałą {weapons} i {armors}.",
