  ["data.otservbr.global.npc.mirabell.L123.158"] = "Oczywiście, rzuć okiem na moje smaczne oferty.",
  ["data.otservbr.global.npc.miraia.L186.1358"] = "Błogosławieństwo Daramana, |PLAYERNAME|. Witaj w Oświeconej Oazie. Usiądź, napij się {drink} albo zjedz coś {food}!",
