  ["data.otservbr.global.npc.nokmir.L98.95"] = "Do zobaczenia, przyjacielu.",
  ["data.otservbr.global.npc.nokmir.L99.96"] = "Do zobaczenia, przyjacielu.",
  ["data.otservbr.global.npc.nomad.L108.168"] = "Ach, kolejny wyznawca skrajności... przetrwanie na lodowatym odludziu? Pozwól, że ci {help}! Jeśli potrzebujesz pierwszej pomocy, mogę cię {healing} albo dać ci {enhanced} błogosławieństwo!",
  ["data.otservbr.global.npc.nomad.L109.169"] = "Trzymaj fason!",
  ["data.otservbr.global.npc.nomad.L110.170"] = "Trzymaj fason!",
  ["data.otservbr.global.npc.noodles.L105.679"] = "<węszy> Hau! <węszy>",
  ["data.otservbr.global.npc.noodles.L106.680"] = "Hau! <merda>",
  ["data.otservbr.global.npc.noodles.L107.681"] = "Hau! <merda>",
  ["data.otservbr.global.npc.noozer.L88.42"] = "Hm? Och! Och, tak, g... gość! Intruz? Dobroczyńca...? Czym... czym ty jesteś? Jeśli chcesz przejść przez tę jaskinię, mogę cię rozczarować. A może nie. To... zależy. Więc, tylko przechodzisz?",
  ["data.otservbr.global.npc.noozer.L89.43"] = "No to cześć.",
  ["data.otservbr.global.npc.nor.L72.1088"] = "[PL] Psst, not that {loud}.",
  ["data.otservbr.global.npc.norf.L105.282"] = "[PL] Welcome, pilgrim. How may I {help} you? Are you in need of {healing}?",
  ["data.otservbr.global.npc.norma.L186.1080"] = "Hej, dokąd idziesz? Przecież dopiero zaczęliśmy!",
  ["data.otservbr.global.npc.norma.L187.1081"] = "Wróć wkrótce!",
  ["data.otservbr.global.npc.norma.L188.1082"] = "Masz tyle czasu, ile potrzebujesz, żeby zdecydować, czego chcesz!",
  ["data.otservbr.global.npc.norma.L189.1083"] = "Witaj, witaj! Siadaj! Jeśli chcesz się napić albo coś zjeść, poproś mnie o {trade}!",
  ["data.otservbr.global.npc.nurik.L105.126"] = "To... to TY! Wreszcie!! Więc jaka to wyjątkowa propozycja, którą chcesz mi złożyć, mój przyjacielu?",
  ["data.otservbr.global.npc.nydala.L57.952"] = "[PL] Welcome to Carlin Furniture Store, |PLAYERNAME|.",
  ["data.otservbr.global.npc.nydala.L58.953"] = "Spójrz. Większość mebli jest w poręcznych zestawach. Użyj ich w domu, aby złożyć meble. Chcesz zobaczyć tylko określony {type} mebli?",
  ["data.otservbr.global.npc.obi.L129.247"] = "Eee, tak, dobrego dnia.",
  ["data.otservbr.global.npc.obi.L130.248"] = "Żegnaj, mam nadzieję, że byłeś zadowolony z naszych usług.",
  ["data.otservbr.global.npc.obi.L131.249"] = "Oczywiście, przejrzyj moje towary.",
  ["data.otservbr.global.npc.obi.L132.250"] = "Witaj, witaj, |PLAYERNAME|! Wejdź, obejrzyj i kup! Jeśli chcesz zobaczyć moje oferty, poproś o {trade}!",
  ["data.otservbr.global.npc.oblivion.L102.1283"] = "Cień cię poprzedził. Czego pragniesz?",
  ["data.otservbr.global.npc.ocelus.L107.832"] = "Pozdrowienia, drogi gościu |PLAYERNAME|.",
