  ["data.otservbr.global.npc.ocelus.L109.834"] = "No cóż.",
  ["data.otservbr.global.npc.oldrak.L197.1032"] = "Witaj |PLAYERNAME|! Rzadko mam teraz okazję gościć {visitors}.",
  ["data.otservbr.global.npc.oldrak.L198.1033"] = "Uważaj, tam na zewnątrz jest niebezpiecznie.",
  ["data.otservbr.global.npc.oldrak.L199.1034"] = "Do widzenia, |PLAYERNAME|",
  ["data.otservbr.global.npc.olrik.L87.581"] = "[PL] Hello. How may I help you |PLAYERNAME|? Ask me for a {trade} if you want to buy something. I can also explain the {mail} system.",
  ["data.otservbr.global.npc.olrik.L88.582"] = "To była przyjemność ci pomóc, |PLAYERNAME|.",
  ["data.otservbr.global.npc.olrik.L89.583"] = "Proszę. Nie zapomnij, że jeśli chcesz wysłać paczkę, musisz też kupić etykietę. Zawsze wpisuj imię {receiver} w pierwszej linii.",
  ["data.otservbr.global.npc.omrabas.L546.362"] = "Wreszcie, gość! Witaj w moim... skromnym przybytku. {Scroll} czy {mission}?",
  ["data.otservbr.global.npc.one.eyed.joe.L81.565"] = "Dobra robota! Ale pamiętaj: przeklęty kryształ wydaje się z czasem regenerować. Może być konieczne, by wrócić i powtórzyć to, co tam zrobiłeś.",
  ["data.otservbr.global.npc.one.eyed.joe.L83.566"] = "Witaj. Wybacz, ledwo cię zauważyłem. Jestem trochę zdenerwowany. Te upiorne {sounds} tam na dole, wiesz...",
