  ["data.otservbr.global.npc.partos.L86.1429"] = "Do widzenia, odwiedź mnie ponownie. Będę tu, obiecuję.",
  ["data.otservbr.global.npc.partos.L87.1430"] = "Do widzenia, odwiedź mnie ponownie. Będę tu, obiecuję.",
