  ["data.otservbr.global.npc.paulie.L346.1574"] = "Miłego dnia.",
  ["data.otservbr.global.npc.paulie.L66.1571"] = "Witaj |PLAYERNAME|! Specjalna oferta dla nowicjuszy, tylko dziś! Wpłać trochę pieniędzy - albo {deposit ALL} swoich pieniędzy! - i odbierz 50 sztuk złota za darmo!",
