  ["data.otservbr.global.npc.romir.L157.1044"] = "Oczywiście, przejrzyj moje towary. A może chcesz zobaczyć tylko",
  ["data.otservbr.global.npc.roswitha.L69.445"] = "Witaj, chłopcze. Usiądź, napij się, czemu nie?",
  ["data.otservbr.global.npc.rottin.wood.L210.1031"] = "Łowieckie pozdrowienie! Zakładam, że czegoś ode mnie chcesz, skoro dotarłeś aż tutaj sam. To niebezpieczne miejsce, wątpię, by wszyscy moi ludzie akceptowali obcych tak jak ja. Ty jednak zdajesz się nie mieć z tym problemu.",
  ["data.otservbr.global.npc.rowenna.L59.475"] = "Witaj w najlepszym sklepie z bronią w krainie, |PLAYERNAME|! Daj znać, jeśli szukasz dobrego {trade}.",
  ["data.otservbr.global.npc.rowenna.L60.476"] = "Do widzenia. Wróć wkrótce.",
  ["data.otservbr.global.npc.rowenna.L61.477"] = "Do widzenia. Wróć wkrótce.",
  ["data.otservbr.global.npc.rowenna.L62.478"] = "Oczywiście, przejrzyj moje towary.",
  ["data.otservbr.global.npc.rudolph.L53.206"] = "Och, klient. Witaj |PLAYERNAME|. Jeśli chcesz zobaczyć moje wspaniałe, własnoręcznie szyte ubrania, poproś o {trade}.",
  ["data.otservbr.global.npc.rudolph.L54.207"] = "Och, do widzenia.",
  ["data.otservbr.global.npc.rudolph.L55.208"] = "Och, do widzenia.",
  ["data.otservbr.global.npc.rudolph.L56.209"] = "Oczywiście, przejrzyj moje towary.",
  ["data.otservbr.global.npc.saideh.L53.693"] = "Witaj, nazywam się Saideh. Kiedyś było tu wejście do krypty naszych bohaterów. Jeden z grobów należy do naszego ukochanego bohatera Dayyana. Obecnie odwiedzanie tego miejsca to niezbyt dobry pomysł.",
  ["data.otservbr.global.npc.saideh.L86.694"] = "No to cześć.",
  ["data.otservbr.global.npc.sam.L153.910"] = "Witaj w moim sklepie, poszukiwaczu przygód |PLAYERNAME|! {trade}uję bronią i pancerzami.",
  ["data.otservbr.global.npc.sam.L154.911"] = "Do widzenia i zapraszam ponownie, |PLAYERNAME|.",
  ["data.otservbr.global.npc.sam.L155.912"] = "Do widzenia i zapraszam ponownie.",
  ["data.otservbr.global.npc.sandomo.L176.5"] = "Hm. Pozdrowienia.",
  ["data.otservbr.global.npc.sandomo.L177.6"] = "Chwała bogom, żegnam cię.",
  ["data.otservbr.global.npc.sandra.L142.1395"] = "[PL] Hello |PLAYERNAME|, welcome to the fluid and potion {shop} of Edron.",
  ["data.otservbr.global.npc.sandra.L143.1396"] = "Do widzenia, |PLAYERNAME|, wróć wkrótce.",
  ["data.otservbr.global.npc.sandra.L144.1397"] = "Do widzenia, |PLAYERNAME|, wróć wkrótce.",
  ["data.otservbr.global.npc.sandra.L145.1398"] = "Oczywiście, przeglądaj moje towary. A tak przy okazji, jeśli chcesz dołączyć do naszego systemu bonusowego za oddawanie flaszek i fiolek, musisz mi o tym powiedzieć przez {deposit}.",
  ["data.otservbr.global.npc.sane.mage.L89.1503"] = "...ee... cześć? Tak...? Cóż, jeśli... jeśli masz jakieś pytania - to mnie tu nawet nie ma.",
  ["data.otservbr.global.npc.sane.mage.L90.1504"] = "Tak... więc do widzenia.",
  ["data.otservbr.global.npc.sane.mage.L91.1505"] = "Tak... więc do widzenia.",
  ["data.otservbr.global.npc.santiago.L101.959"] = "Witaj z powrotem! Gdzie to byliśmy...? Ach, tak, pytałem, czy widziałeś swój „level up”! Widziałeś, {right}?",
  ["data.otservbr.global.npc.santiago.L104.960"] = "Witaj z powrotem! Gdzie to byliśmy...? Ach, tak, pytałem, czy te paskudne karaluchy cię {hurt}! Ugryzły?",
  ["data.otservbr.global.npc.santiago.L107.961"] = "Witaj z powrotem! Gdzie to byliśmy...? Ach, tak, pytałem, czy mam ci pokazać trochę obrażeń. Zróbmy to, {okay}?",
  ["data.otservbr.global.npc.santiago.L110.962"] = "Witaj z powrotem! Gdzie to byliśmy...? Ach, tak, miałem pokazać, jak odzyskujesz zdrowie, prawda?",
  ["data.otservbr.global.npc.santiago.L113.963"] = "Witaj z powrotem! Gdzie to byliśmy...? Ach, tak, dałem ci rybę do zjedzenia?",
  ["data.otservbr.global.npc.santiago.L116.964"] = "Witaj z powrotem! Gdzie to byliśmy...? Ach, tak, pytałem, czy widziałeś Zirellę! Widziałeś?",
  ["data.otservbr.global.npc.santiago.L119.965"] = "Witaj ponownie, |PLAYERNAME|! Świetnie cię widzieć. Jeśli chcesz, możemy chwilę pogadać. Użyj ponownie podświetlonych {keywords}, aby wybrać {topic}.",
  ["data.otservbr.global.npc.santiago.L250.966"] = "Uważaj, |PLAYERNAME|.",
  ["data.otservbr.global.npc.santiago.L251.967"] = "Do widzenia, podróżniku, miłego pobytu na Rookgaard.",
  ["data.otservbr.global.npc.santiago.L70.954"] = "Witaj |PLAYERNAME|, miło cię widzieć na Rookgaard! Widziałem, jak przechodziłeś, i pomyślałem, że może mi pomożesz. Pomożesz? Proszę, powiedz {yes}!",
  ["data.otservbr.global.npc.santiago.L73.955"] = "Och, |PLAYERNAME|, znowu ty! Pewnie to niegrzeczne przeszkadzać zapracowanemu awanturnikowi takiemu jak ty, ale naprawdę potrzebuję pomocy. Proszę, powiedz {yes}!",
  ["data.otservbr.global.npc.santiago.L80.956"] = "Witaj z powrotem, |PLAYERNAME|! Ahh, znalazłeś moją skrzynię. Pozwól, że cię obejrzę. Założyłeś ten płaszcz, {yes}?",
  ["data.otservbr.global.npc.santiago.L83.957"] = "Hej, chcę dać ci broń za darmo! Nie powinieneś odmawiać, właściwie powinieneś powiedzieć '{yes}'!",
  ["data.otservbr.global.npc.santiago.L90.958"] = "Dobra robota! Za to dam ci 100 punktów doświadczenia! O - co to było? Chyba awansowałeś poziom, {right}?",
  ["data.otservbr.global.npc.sarina.L86.73"] = "Och, wejdź proszę, |PLAYERNAME|. Co mogę dla ciebie zrobić? Jeśli potrzebujesz sprzętu na wyprawę, poproś o {trade}.",
  ["data.otservbr.global.npc.sarina.L87.74"] = "Do widzenia, |PLAYERNAME|.",
  ["data.otservbr.global.npc.sarina.L88.75"] = "Do widzenia, |PLAYERNAME|.",
  ["data.otservbr.global.npc.sarina.L89.76"] = "Oczywiście, przejrzyj moje towary. {Footballs} trzeba kupić osobno.",
  ["data.otservbr.global.npc.scrutinon.L101.1548"] = "|PLAYERNAME|. Od dłuższego czasu obserwuję twój los. Najwyższa pora, że tu dotarłeś. Chcesz wejść na rozdarte wyspy Quirefang, czy wrócić tam, skąd przyszedłeś?",
  ["data.otservbr.global.npc.sebastian.L116.1348"] = "Pozdrowienia, śmiały poszukiwaczu przygód. Jeśli potrzebujesz {passage}, daj znać.",
  ["data.otservbr.global.npc.sebastian.L117.1349"] = "Do widzenia.",
  ["data.otservbr.global.npc.sebastian.L118.1350"] = "No cóż.",
  ["data.otservbr.global.npc.sebastian.nargor.L68.1109"] = "Pozdrowienia, śmiały poszukiwaczu przygód. Jeśli potrzebujesz {passage}, daj znać.",
  ["data.otservbr.global.npc.sebastian.nargor.L69.1110"] = "Do widzenia.",
  ["data.otservbr.global.npc.sebastian.nargor.L70.1111"] = "No cóż.",
  ["data.otservbr.global.npc.serafin.L78.1045"] = "Witaj w moim sklepie z owocami i warzywami, |PLAYERNAME|! Poproś o {trade}, jeśli chcesz zobaczyć moje towary.",
  ["data.otservbr.global.npc.servant.sentry.L94.222"] = "Szlam. Wszedł. Nasz. Mistrz. Odszedł! My. Musimy. Pomóc.",
  ["data.otservbr.global.npc.servant.sentry.L95.223"] = "Żegnaj. Czło. Wieku!",
  ["data.otservbr.global.npc.servant.sentry.L96.224"] = "Żegnaj. Czło. Wieku!",
  ["data.otservbr.global.npc.seymour.L243.46"] = "Do widzenia! I pamiętaj: żadnego biegania w górę i w dół po akademii!",
  ["data.otservbr.global.npc.shanar.L64.783"] = "Do widzenia!",
  ["data.otservbr.global.npc.shauna.L128.135"] = "Czołem, |PLAYERNAME|!",
  ["data.otservbr.global.npc.shauna.L129.136"] = "NIECH ŻYJE KRÓLOWA!",
  ["data.otservbr.global.npc.shauna.L130.137"] = "NIECH ŻYJE KRÓLOWA!",
  ["data.otservbr.global.npc.sherry.mcronald.L59.404"] = "Witaj |PLAYERNAME|! Witamy na naszej skromnej farmie.",
  ["data.otservbr.global.npc.sherry.mcronald.L60.405"] = "Zaszczyć nasz dom kolejną wizytą wkrótce, |PLAYERNAME|.",
  ["data.otservbr.global.npc.sherry.mcronald.L61.406"] = "Co za dziwna osoba.",
  ["data.otservbr.global.npc.shiantis.L86.703"] = "Och, wejdź proszę, |PLAYERNAME|. Co mogę dla ciebie zrobić? Jeśli potrzebujesz sprzętu na wyprawę, poproś o {trade}.",
  ["data.otservbr.global.npc.shiantis.L87.704"] = "Do widzenia, |PLAYERNAME|.",
  ["data.otservbr.global.npc.shiantis.L88.705"] = "Do widzenia, |PLAYERNAME|.",
  ["data.otservbr.global.npc.shiantis.L89.706"] = "Oczywiście, przejrzyj moje towary.",
