  ["data.otservbr.global.npc.shiriel.L142.1146"] = "Pozdrowienia, |PLAYERNAME|.",
  ["data.otservbr.global.npc.shiriel.L143.1147"] = "Do widzenia, |PLAYERNAME|.",
  ["data.otservbr.global.npc.shiriel.L144.1148"] = "Do widzenia, |PLAYERNAME|.",
  ["data.otservbr.global.npc.shiriel.L145.1149"] = "Oczywiście, przejrzyj moje towary. A może chcesz zobaczyć tylko",
  ["data.otservbr.global.npc.shirith.L87.15"] = "Ashari, |PLAYERNAME|!",
  ["data.otservbr.global.npc.shirith.L88.16"] = "Do widzenia!",
  ["data.otservbr.global.npc.shirith.L89.17"] = "Do widzenia!",
  ["data.otservbr.global.npc.shirtalis.of.the.summer.court.L83.56"] = "Witaj, wojowniku. Zgaduję, że jesteś tu, by {fight} za naszą szlachetną {cause}.",
  ["data.otservbr.global.npc.shirtalis.of.the.summer.court.L84.57"] = "No to cześć.",
  ["data.otservbr.global.npc.shoddy.beggar.L172.53"] = "Czego chcesz? Posłuchać starego szaleńca? Jeśli nie masz nic do oddania, zostaw mnie w spokoju.",
  ["data.otservbr.global.npc.shoddy.beggar.L173.54"] = "Tak, cokolwiek.",
  ["data.otservbr.global.npc.shoddy.beggar.L174.55"] = "Tak, cokolwiek.",
  ["data.otservbr.global.npc.sholley.L83.547"] = "Cześć!",
  ["data.otservbr.global.npc.siestaar.L76.570"] = "Tak? Co mogę dla ciebie zrobić, |PLAYERNAME|? Może sprawy bankowe?",
  ["data.otservbr.global.npc.siestaar.L77.571"] = "Miłego dnia.",
  ["data.otservbr.global.npc.siestaar.L78.572"] = "Miłego dnia.",
  ["data.otservbr.global.npc.siflind.L214.1557"] = "Witaj, |PLAYERNAME|. Jeśli potrzebujesz mikstur lub magicznego wyposażenia, zapytaj o moje {offers}.",
  ["data.otservbr.global.npc.sigurd.L144.1168"] = "Witaj w sklepie magicznym, |PLAYERNAME|! Poproś mnie o trade, jeśli czegoś potrzebujesz.",
  ["data.otservbr.global.npc.sigurd.L145.1169"] = "Do widzenia. Wróć wkrótce.",
  ["data.otservbr.global.npc.sigurd.L146.1170"] = "Do widzenia. Wróć wkrótce.",
  ["data.otservbr.global.npc.sigurd.L147.1171"] = "Oczywiście, przejrzyj moje towary. A może chcesz zobaczyć tylko",
  ["data.otservbr.global.npc.simon.the.beggar.L315.1138"] = "Witaj |PLAYERNAME|. Jestem biednym człowiekiem. Proszę, pomóż mi.",
  ["data.otservbr.global.npc.simon.the.beggar.L316.1139"] = "Miłego dnia.",
  ["data.otservbr.global.npc.simon.the.beggar.L317.1140"] = "Miłego dnia.",
  ["data.otservbr.global.npc.sinclair.L157.1276"] = "Pozdrowienia |PLAYERNAME|. Mam - bardzo - mało czasu, więc mów możliwie krótko. Być może pomogę ci, jeśli jesteś tu, by pomóc nam w zadaniach lub misjach.",
  ["data.otservbr.global.npc.sinclair.L158.1277"] = "Do widzenia i powodzenia, |PLAYERNAME|.",
  ["data.otservbr.global.npc.sinclair.L159.1278"] = "Do widzenia i powodzenia, |PLAYERNAME|.",
  ["data.otservbr.global.npc.sissek.L71.1049"] = "Tak? Co mogę dla ciebie zrobić, |PLAYERNAME|? Może sprawy bankowe?",
  ["data.otservbr.global.npc.sissek.L72.1050"] = "Miłego dnia.",
  ["data.otservbr.global.npc.sissek.L73.1051"] = "Miłego dnia.",
  ["data.otservbr.global.npc.sister.of.jack.L106.611"] = "Mh, witaj. Co mogę dla ciebie zrobić?",
  ["data.otservbr.global.npc.skjaar.L89.1578"] = "Kolejne stworzenie, które uważa, że siła fizyczna jest ważniejsza od mądrości! Czemu mi przeszkadzasz?",
  ["data.otservbr.global.npc.skjaar.L90.1579"] = "Żegnaj, |PLAYERNAME|!",
  ["data.otservbr.global.npc.skjaar.L91.1580"] = "Uciekaj, niegodny |PLAYERNAME|!",
  ["data.otservbr.global.npc.spectulus.L492.816"] = "Witaj |PLAYERNAME|! Spóźniłeś się, czy nie masz pojęcia o czasie? Moja misja jest najwyższej wagi. Jeśli nie chcesz mi pomóc, możesz po prostu odejść.",
  ["data.otservbr.global.npc.spectulus.L493.817"] = "Tak, tak. Do widzenia, |PLAYERNAME|.",
  ["data.otservbr.global.npc.spectulus.L494.818"] = "Tak, tak. Do widzenia, |PLAYERNAME|.",
  ["data.otservbr.global.npc.spectulus.L67.814"] = "Witaj |PLAYERNAME|! Spóźniłeś się, czy nie masz pojęcia o czasie? Moja misja jest najwyższej wagi. Jeśli nie chcesz mi pomóc, możesz po prostu odejść.",
  ["data.otservbr.global.npc.spectulus.L70.815"] = "Ach, witaj ponownie |PLAYERNAME|! Wciąż mam dla ciebie jedną lub dwie inne {missions}. Są też pewne {tasks}, którymi ktoś musi się zająć.",
  ["data.otservbr.global.npc.stricken.soul.L53.1482"] = "To miejsce jest... nawiedzone... posłuchaj mojego ostrzeżenia... są tu... duuuuuuchy...! Czemu patrzysz na mnie tak... dziwnie? Jestem pewien, że tu naaaaaaprawdę są duchy - widziałem je! Wierzysz mi?",
  ["data.otservbr.global.npc.stricken.soul.L55.1483"] = "Poz... drowienia.",
  ["data.otservbr.global.npc.stutch.L84.1270"] = "NIECH ŻYJE KRÓL!",
  ["data.otservbr.global.npc.stutch.L85.1271"] = "NIECH ŻYJE KRÓL! Możesz już odejść!",
  ["data.otservbr.global.npc.sundara.L170.1087"] = "Oczywiście, przejrzyj moje towary. A może chcesz zobaczyć tylko",
  ["data.otservbr.global.npc.suzy.L76.1112"] = "Tak? Co mogę dla ciebie zrobić, |PLAYERNAME|? Może sprawy bankowe?",
  ["data.otservbr.global.npc.suzy.L77.1113"] = "Miłego dnia.",
  ["data.otservbr.global.npc.suzy.L78.1114"] = "Miłego dnia.",
  ["data.otservbr.global.npc.sven.L55.603"] = "Iskan powiedział mi, że zabijałeś husky tutaj, w Svargrond. Będę dla ciebie łagodny i nie wygnam cię ze Svargrond. Ale musisz zapłacić mi 1500 sztuk złota odszkodowania za każdego zabitego husky. Czy jesteś gotów zapłacić",
  ["data.otservbr.global.npc.sven.L57.604"] = "[PL] Be greeted, |PLAYERNAME|! What brings you {here}?",
  ["data.otservbr.global.npc.swolt.L111.235"] = "Spójrz, ale ani łyka, zanim nie zapłacisz. I mam nadzieję, że tak zostanie i nie przyjdą ci do głowy dziwne pomysły dotyczące {rice}.",
  ["data.otservbr.global.npc.taegen.L203.752"] = "Witaj, śmiertelna istoto!",
  ["data.otservbr.global.npc.taegen.L204.753"] = "Niech oświecenie prowadzi twoją drogę, |PLAYERNAME|.",
  ["data.otservbr.global.npc.taegen.L205.754"] = "Niech oświecenie prowadzi twoją drogę, |PLAYERNAME|.",
  ["data.otservbr.global.npc.taegen.L206.755"] = "Rzeźbię bełty i strzały, a także tworzę łuki i włócznie. Jeśli chcesz kupić amunicję, rzuć okiem.",
  ["data.otservbr.global.npc.talila.L61.1453"] = "Pozdrowienia, śmiertelna istoto.",
  ["data.otservbr.global.npc.talila.L62.1454"] = "Tak, mam kilka mikstur i run, jeśli jesteś zainteresowany. Chcesz kupić tylko mikstury albo tylko runy? Och, jeśli chcesz sprzedawać lub kupować klejnoty, też możesz zapytać.",
  ["data.otservbr.global.npc.talila.L63.1455"] = "Niech oświecenie prowadzi twoją drogę, |PLAYERNAME|.",
  ["data.otservbr.global.npc.tamerin.L58.283"] = "[PL] Have you the {animal cure}?",
  ["data.otservbr.global.npc.tamerin.L60.284"] = "Zabiłeś {morik}?",
  ["data.otservbr.global.npc.tamerin.L62.285"] = "Witaj, co cię tu sprowadza?",
  ["data.otservbr.global.npc.tamoril.L113.1311"] = "Kolejny namolny śmiertelnik, który uważa, że jego złoto przewyższa jego wartość odżywczą.",
  ["data.otservbr.global.npc.tamoril.L61.1310"] = "O Pierwszym Smoku możesz rozmawiać tylko między 14 stycznia a 12 lutego.",
  ["data.otservbr.global.npc.tandros.L160.196"] = "Oczywiście, przejrzyj moje towary. A może chcesz zobaczyć tylko",
  ["data.otservbr.global.npc.tanyt.L100.1187"] = "Ach, wiatr przywiał kolejnego gościa. Witaj, drogi gościu. Szukasz {passage} na moim dywanie?",
  ["data.otservbr.global.npc.tanyt.L101.1188"] = "Do widzenia. Poleć nas, jeśli byłeś zadowolony z naszej obsługi.",
  ["data.otservbr.global.npc.tanyt.L102.1189"] = "W takim razie do widzenia.",
  ["data.otservbr.global.npc.tarak.inner.L88.682"] = "[PL] Can I interest you in a trip to the {monument tower}?",
  ["data.otservbr.global.npc.tarak.sunken.L75.868"] = "Chcesz wrócić do Yalahar? Po prostu poproś mnie o darmowe {passage}.",
  ["data.otservbr.global.npc.tarun.L116.1563"] = "Pozdrowienia!",
  ["data.otservbr.global.npc.tarun.L117.1564"] = "Żegnaj.",
  ["data.otservbr.global.npc.tarun.L118.1565"] = "Oczywiście, po prostu spójrz.",
  ["data.otservbr.global.npc.tarun.L121.1566"] = "Żegnaj.",
  ["data.otservbr.global.npc.tefrit.L119.537"] = "No to cześć.",
