  ["data.otservbr.global.npc.tefrit.L61.535"] = "Jak mogę pomóc?",
  ["data.otservbr.global.npc.tefrit.L64.536"] = "Jak mogę pomóc?",
  ["data.otservbr.global.npc.tehlim.L76.419"] = "Do zobaczenia, przyjacielu.",
  ["data.otservbr.global.npc.tehlim.L77.420"] = "Do zobaczenia, przyjacielu.",
  ["data.otservbr.global.npc.tehlim.L78.421"] = "Witaj. Tak się cieszę, że ktoś mnie znalazł. Spotkałeś ICH?!",
  ["data.otservbr.global.npc.telas.L103.1028"] = "Witaj!",
  ["data.otservbr.global.npc.telas.golem.L54.279"] = "Gdzie... ja jestem?",
  ["data.otservbr.global.npc.telas.golem.L55.280"] = "Do... widzenia.",
  ["data.otservbr.global.npc.telas.golem.L56.281"] = "Do... widzenia.",
  ["data.otservbr.global.npc.tereban.L61.592"] = "Pozdrowienia, przyjacielu. Dobrze, że się pojawiłeś.",
  ["data.otservbr.global.npc.terrence.L75.456"] = "Hej, na pewno interesuje cię pomoc straży miejskiej Rathleton, prawda? Szczególnie teraz, gdy przerażające minotaury każdego dnia zdobywają coraz więcej terenu.",
  ["data.otservbr.global.npc.tesha.L76.913"] = "Tak? Co mogę dla ciebie zrobić, |PLAYERNAME|? Może sprawy bankowe?",
  ["data.otservbr.global.npc.tesha.L77.914"] = "Miłego dnia.",
  ["data.otservbr.global.npc.tesha.L78.915"] = "Miłego dnia.",
  ["data.otservbr.global.npc.testserver.assistant.L116.455"] = "[PL] Hey |PLAYERNAME|. I'm Testserver Assistant and I can give {money}, {experience} and {blessing} which will be useful for testing on",
  ["data.otservbr.global.npc.testserver.assistant.L89.453"] = "Masz już błogosławieństwo.",
  ["data.otservbr.global.npc.testserver.assistant.L98.454"] = "Otrzymałeś pozostałe",
  ["data.otservbr.global.npc.thanita.L86.1073"] = "Jak mogłeś się tak do mnie zakraść? Myślałam, że jesteś jednym z NICH! Skoro jednak nie jesteś, to co sprowadza cię na to pustkowie?",
  ["data.otservbr.global.npc.thanita.L87.1074"] = "Uważaj na siebie, podróżniku. Szkoda byłoby stracić tak odważnego wędrowca przez te zielone potwory.",
  ["data.otservbr.global.npc.thanita.L88.1075"] = "Uważaj na siebie, podróżniku. Szkoda byłoby stracić tak odważnego wędrowca przez te zielone potwory.",
  ["data.otservbr.global.npc.the.beggar.king.L103.328"] = "Cześć! Wyglądasz na kogoś będącego na {mission}.",
  ["data.otservbr.global.npc.the.beggar.king.L104.329"] = "Do widzenia!",
  ["data.otservbr.global.npc.the.blind.prophet.L69.426"] = "Witaj, przyjacielu małp.",
  ["data.otservbr.global.npc.the.bone.master.L138.464"] = "Witaj w moim małym królestwie.",
  ["data.otservbr.global.npc.the.bone.master.L139.465"] = "Spotkamy się ponownie.",
  ["data.otservbr.global.npc.the.crone.L54.397"] = "Witaj, |PLAYERNAME|... śmiertelniku.",
  ["data.otservbr.global.npc.the.dream.master.L134.676"] = "Witaj, przybyszu.",
  ["data.otservbr.global.npc.the.dream.master.L135.677"] = "Do widzenia. Niech bogowie czuwają nad twoją drogą.",
  ["data.otservbr.global.npc.the.empress.L78.443"] = "Pozdrowienia.",
  ["data.otservbr.global.npc.the.empress.L84.444"] = "No to cześć.",
  ["data.otservbr.global.npc.the.first.dragon.L149.1115"] = "Witaj, mój towarzyszu sparingów. Powinniśmy kiedyś jeszcze zawalczyć. Myślę, że zasłużyłeś na małą nagrodę.",
  ["data.otservbr.global.npc.the.librarian.L86.394"] = "Pozdrowienia, drogi gościu. Jeśli interesują cię artykuły papiernicze, takie jak książki czy zwoje, poproś mnie o trade.",
  ["data.otservbr.global.npc.the.librarian.L87.395"] = "No to cześć.",
  ["data.otservbr.global.npc.the.lootmonger.L72.1308"] = "[PL] Ah, a customer! Be greeted, |PLAYERNAME|! I buy all kinds of loot, would you like a {trade}? I can also show you my {shop options}.",
  ["data.otservbr.global.npc.the.lootmonger.L73.1309"] = "Ach, klient! Witaj, |PLAYERNAME|! Kupuję wszelkiego rodzaju łupy, może chcesz spojrzeć na",
  ["data.otservbr.global.npc.the.oracle.L164.499"] = "WRÓĆ, GDY BĘDZIESZ GOTÓW STAWIĆ CZOŁA SWOJEMU PRZEZNACZENIU!",
  ["data.otservbr.global.npc.the.oracle.L165.500"] = "WRÓĆ, GDY BĘDZIESZ GOTÓW STAWIĆ CZOŁA SWOJEMU PRZEZNACZENIU!",
  ["data.otservbr.global.npc.the.orc.king.L61.114"] = "Harrrrk! Myślisz, że jesteś teraz silny? Nigdy nie uciekniesz przed moim gniewem! Jestem nieśmiertelny!",
  ["data.otservbr.global.npc.the.queen.of.the.banshees.L215.943"] = "Witaj, drogi gościu. Chodź i {stay}... chwilę.",
  ["data.otservbr.global.npc.the.queen.of.the.banshees.L216.944"] = "Spotkamy się ponownie, |PLAYERNAME|.",
  ["data.otservbr.global.npc.the.queen.of.the.banshees.L217.945"] = "Tak, uciekaj przed śmiercią. Ale wiedz, że zawsze będzie jeden krok za tobą.",
  ["data.otservbr.global.npc.thorgrin.L67.258"] = "Witaj, |PLAYERNAME|! Niech ziemia chroni cię na kamienistych terenach. Jeśli potrzebujesz powrotnego {passage}, mogę pomóc.",
  ["data.otservbr.global.npc.thorgrin.L68.259"] = "Do widzenia.",
  ["data.otservbr.global.npc.thorgrin.L69.260"] = "W takim razie do widzenia.",
  ["data.otservbr.global.npc.thorwulf.L223.907"] = "Cześć |PLAYERNAME|.",
  ["data.otservbr.global.npc.thorwulf.L224.908"] = "Pa |PLAYERNAME|.",
  ["data.otservbr.global.npc.thorwulf.L225.909"] = "Cześć.",
  ["data.otservbr.global.npc.tibra.L137.512"] = "Witaj w imieniu bogów, pielgrzymie |PLAYERNAME|!",
  ["data.otservbr.global.npc.tibra.L138.513"] = "Do widzenia, |PLAYERNAME|. Niech bogowie będą z tobą, by cię strzec i prowadzić, moje dziecko!",
  ["data.otservbr.global.npc.tigo.L59.857"] = "Spokojnie, nowicjuszu. Teraz staniesz się jednym z nas, jak wielu przed tobą. Jednym z {Barkless}. Idź z nami, a będziesz kroczyć dumnie, mój przyjacielu.",
  ["data.otservbr.global.npc.tigo.L96.858"] = "No to cześć.",
  ["data.otservbr.global.npc.tim.the.guard.L93.608"] = "NIECH ŻYJE KRÓL!",
  ["data.otservbr.global.npc.tim.the.guard.L94.609"] = "NIECH ŻYJE KRÓL!",
  ["data.otservbr.global.npc.tim.the.guard.L95.610"] = "NIECH ŻYJE KRÓL!",
  ["data.otservbr.global.npc.timothy.L82.683"] = "Och, witaj! Miło zobaczyć gościa z kontynentu.",
  ["data.otservbr.global.npc.timur.L60.1070"] = "Witaj w moim małym sklepie, poszukiwaczu przygód! Najpierw przeczytaj moje tablice.",
  ["data.otservbr.global.npc.timur.L61.1071"] = "Pa, pa.",
  ["data.otservbr.global.npc.timur.L62.1072"] = "Pa, pa.",
  ["data.otservbr.global.npc.todd.L83.450"] = "[PL] Uhm oh hello |PLAYERNAME|... not so loud please... my {head}... What ... do you {want}?",
  ["data.otservbr.global.npc.todd.L84.451"] = "Tak, do widzenia |PLAYERNAME|, po prostu zostaw mnie w spokoju.",
  ["data.otservbr.global.npc.todd.L85.452"] = "Wreszcie cisza.",
  ["data.otservbr.global.npc.tom.L264.1441"] = "Eee?",
  ["data.otservbr.global.npc.tom.L265.1442"] = "Jasne, sprawdź, co kupuję.",
  ["data.otservbr.global.npc.tom.L66.1435"] = "[PL] Hey there, |PLAYERNAME|. Did Vascalir send you to me for a {mission}?",
  ["data.otservbr.global.npc.tom.L69.1436"] = "No, no - z tym nie da się pracować. Wróć do wilczej nory i dokończ misję! Chyba że jest coś jeszcze, w czym mogę ci pomóc.",
  ["data.otservbr.global.npc.tom.L72.1437"] = "Hej, |PLAYERNAME|. Wyglądasz... na wykończonego. Dużo biegałeś? I co ważniejsze, udało ci się znaleźć trochę skóry wilka wojennego?",
  ["data.otservbr.global.npc.tom.L74.1438"] = "Hej, |PLAYERNAME|. Jestem Tom garbarz. Jeśli masz świeże {corpses}, skóry, łapy lub inne części zwierzęcych ciał, {trade}uj ze mną.",
  ["data.otservbr.global.npc.tom.L84.1439"] = "Udanych łowów, dziecko.",
  ["data.otservbr.global.npc.tom.L86.1440"] = "Udanych łowów, synu.",
  ["data.otservbr.global.npc.tomruk.the.ruddy.L126.1287"] = "Witaj, witaj! Zawsze dobrze widzieć świeżą krew! Co cię tu sprowadza?",
  ["data.otservbr.global.npc.tonar.L72.1207"] = "Witaj, Sir.",
  ["data.otservbr.global.npc.tonar.oskayaat.L72.1247"] = "Witaj ponownie, Sir.",
  ["data.otservbr.global.npc.topsy.L181.925"] = "Oczywiście, przejrzyj moje towary. A może chcesz zobaczyć tylko",
  ["data.otservbr.global.npc.topsy.L182.926"] = "Do widzenia, |PLAYERNAME|. Koniecznie wróć!",
  ["data.otservbr.global.npc.topsy.L183.927"] = "Do widzenia, |PLAYERNAME|. Koniecznie wróć!",
  ["data.otservbr.global.npc.torkada.L96.1008"] = "Pozdrowienia! To nie jest pora na pogaduszki, {time}.",
  ["data.otservbr.global.npc.torkada.L97.1009"] = "Cześć.",
  ["data.otservbr.global.npc.torkada.L98.1010"] = "Do widzenia, |PLAYERNAME|.",
  ["data.otservbr.global.npc.trisha.L104.108"] = "Witaj z powrotem, rycerzu |PLAYERNAME|!",
  ["data.otservbr.global.npc.trisha.L234.109"] = "Uważaj w podróży.",
  ["data.otservbr.global.npc.trisha.L235.110"] = "Nie zrób sobie krzywdy tą bronią, maluchu.",
  ["data.otservbr.global.npc.turvy.L58.372"] = "Witaj, drogi |PLAYERNAME|. Czy mogę jakoś pomóc? Powiedz tylko, jeśli chcesz {trade} bronią albo pancerzem.",
  ["data.otservbr.global.npc.turvy.L59.373"] = "Do widzenia, |PLAYERNAME|. Koniecznie wróć!.",
  ["data.otservbr.global.npc.turvy.L60.374"] = "Do widzenia, |PLAYERNAME|. Koniecznie wróć!.",
  ["data.otservbr.global.npc.turvy.L61.375"] = "Oczywiście, przejrzyj moje oferty.",
  ["data.otservbr.global.npc.tyrias.L173.1272"] = "Witaj, młody |PLAYERNAME|! Jeśli jesteś ciężko ranny lub zatruty, mogę cię za darmo {heal}.",
  ["data.otservbr.global.npc.tyrias.L174.1273"] = "Pamiętaj: jeśli jesteś ciężko ranny lub zatruty, mogę cię uleczyć za darmo.",
  ["data.otservbr.global.npc.tyrias.L175.1274"] = "Niech bogowie ci błogosławią, |PLAYERNAME|!",
  ["data.otservbr.global.npc.ubaid.L175.124"] = "Żegnaj, człowieku!",
  ["data.otservbr.global.npc.ubaid.L176.125"] = "Żegnaj, człowieku!",
  ["data.otservbr.global.npc.ukea.L57.1102"] = "Do widzenia!",
  ["data.otservbr.global.npc.ulala.L136.675"] = "Duchy cię witają.",
  ["data.otservbr.global.npc.umar.L162.1233"] = "<salutuje>Aaaa -baczność!",
  ["data.otservbr.global.npc.umar.L163.1234"] = "<salutuje>Aaaa -baczność!",
  ["data.otservbr.global.npc.undal.L167.1466"] = "Pozdrowienia, bohaterze. Zgaduję, że przyszedłeś {talk}.",
  ["data.otservbr.global.npc.undal.L168.1467"] = "No to cześć.",
  ["data.otservbr.global.npc.undal.L169.1468"] = "No to cześć.",
  ["data.otservbr.global.npc.urks.the.mute.L73.1084"] = "Witaj, |PLAYERNAME|! Piękny parowiec, prawda? Mogę nawet zaoferować ci {passage}, jeśli chcesz.",
  ["data.otservbr.global.npc.urks.the.mute.L74.1085"] = "Do następnego razu.",
  ["data.otservbr.global.npc.urks.the.mute.L75.1086"] = "Do następnego razu.",
  ["data.otservbr.global.npc.ustan.L91.1076"] = "Błogosławieństwo Crunora, podróżniku.",
  ["data.otservbr.global.npc.uzgod.L146.1355"] = "Hejho |PLAYERNAME|! Chcesz broń, co?",
  ["data.otservbr.global.npc.uzgod.L147.1356"] = "Do widzenia. Wróć wkrótce.",
  ["data.otservbr.global.npc.uzgod.L148.1357"] = "Do widzenia. Wróć wkrótce.",
  ["data.otservbr.global.npc.uzon.L115.987"] = "Błogosławieństwo Daramana, podróżniku |PLAYERNAME|.",
  ["data.otservbr.global.npc.uzon.L116.988"] = "Błogosławieństwo Daramana",
  ["data.otservbr.global.npc.uzon.L117.989"] = "Błogosławieństwo Daramana",
  ["data.otservbr.global.npc.uzon.back.L80.47"] = "Błogosławieństwo Daramana, podróżniku |PLAYERNAME|.",
  ["data.otservbr.global.npc.uzon.back.L81.48"] = "Błogosławieństwo Daramana",
  ["data.otservbr.global.npc.uzon.back.L82.49"] = "Błogosławieństwo Daramana",
  ["data.otservbr.global.npc.valentina.L83.544"] = "Witamy w sklepie walentynkowym. Zróbmy {trade} coś?",
  ["data.otservbr.global.npc.valentina.L84.545"] = "Wpadaj od czasu do czasu.",
  ["data.otservbr.global.npc.valentina.L85.546"] = "Wpadaj od czasu do czasu.",
  ["data.otservbr.global.npc.valindara.L66.1597"] = "Pozdrowienia, śmiertelna istoto.",
  ["data.otservbr.global.npc.valindara.L67.1598"] = "Tak, mam kilka mikstur i run, jeśli jesteś zainteresowany. Chcesz kupić tylko mikstury albo tylko runy? Och, jeśli chcesz sprzedawać lub kupować klejnoty, też możesz zapytać.",
  ["data.otservbr.global.npc.valindara.L68.1599"] = "Niech oświecenie prowadzi twoją drogę, |PLAYERNAME|.",
  ["data.otservbr.global.npc.vanys.L167.531"] = "Pozdrowienia, bohaterze. Zgaduję, że przyszedłeś {talk}.",
  ["data.otservbr.global.npc.vanys.L168.532"] = "No to cześć.",
  ["data.otservbr.global.npc.vanys.L169.533"] = "No to cześć.",
  ["data.otservbr.global.npc.vascalir.L100.1525"] = "Witaj z powrotem, |PLAYERNAME|. Dobrze widzieć, że wróciłeś cały. Mam nadzieję, że nie jesteś zbyt wyczerpany, bo znów przydałaby mi się twoja {help}.",
  ["data.otservbr.global.npc.vascalir.L103.1526"] = "Och, witaj |PLAYERNAME|! Zdecydowałeś już, czy wkradniesz się do legowiska tarantuli i zdobędziesz próbkę jej pajęczyny? Podejmiesz się tego?",
  ["data.otservbr.global.npc.vascalir.L106.1527"] = "Potrzebujesz ponownie instrukcji do legowiska tarantuli?",
  ["data.otservbr.global.npc.vascalir.L109.1528"] = "Och, świetna robota! Daj, wezmę od ciebie próbkę tej pajęczyny - ostrożnie, ostrożnie... jest wytrzymała, ale krucha. Dziękuję! Powinienem móc zrobić z tego świetną pułapkę paraliżującą. Proszę, mam też coś solidnego dla ciebie - chcesz?",
  ["data.otservbr.global.npc.vascalir.L114.1529"] = "Witaj z powrotem, |PLAYERNAME|! Co z tym ćwiekowanym pancerzem - chcesz go teraz?",
  ["data.otservbr.global.npc.vascalir.L121.1530"] = "|PLAYERNAME|! Dzięki bogom wróciłeś! Gdy cię nie było, wydarzyło się coś strasznego. Czujesz zapach ognia?",
  ["data.otservbr.global.npc.vascalir.L128.1531"] = "O rany, co stało się z twoimi włosami? Twoja twarz też jest cała czarna - na dole musiało być piekło płomieni. To bardzo odważne z twojej strony. Zdobyłeś księgę?",
  ["data.otservbr.global.npc.vascalir.L131.1532"] = "Czy jesteś gotów na kolejną misję, |PLAYERNAME|?",
  ["data.otservbr.global.npc.vascalir.L138.1533"] = "Skoro już wiesz, jak przechowywać pieniądze, czas ruszyć po trolli. Dam ci nawet trochę dodatkowego wyposażenia w nagrodę. Czujesz się gotów na tę misję?",
  ["data.otservbr.global.npc.vascalir.L145.1534"] = "|PLAYERNAME|, witaj z powrotem! To była świetna robota. Daj, dam ci coś za twoje starania - zasłużyłeś. Proszę, chcesz hełm?",
  ["data.otservbr.global.npc.vascalir.L150.1535"] = "Pozdrowienia, |PLAYERNAME|. Masz teraz dość miejsca na mosiężny hełm?",
  ["data.otservbr.global.npc.vascalir.L153.1536"] = "Pozdrowienia, |PLAYERNAME|. Jesteś gotów na kolejną misję?",
  ["data.otservbr.global.npc.vascalir.L156.1537"] = "Pozdrowienia, |PLAYERNAME|. Widzę, że nie zbadałeś jeszcze całej krypty - potrzebujesz znów wyjaśnień?",
  ["data.otservbr.global.npc.vascalir.L159.1538"] = "Witaj z powrotem, |PLAYERNAME|! Znalazłeś w krypcie ładną, mięsistą kość?",
  ["data.otservbr.global.npc.vascalir.L162.1539"] = "Witaj z powrotem, |PLAYERNAME|! Masz teraz dość miejsca na ten miecz?",
  ["data.otservbr.global.npc.vascalir.L165.1540"] = "Pozdrowienia, |PLAYERNAME|! Muszę przyznać, że mam świetny nastrój. Prawie udało nam się przeniknąć do kryjówki Kraknaknorka. Mam jeszcze jedną małą prośbę i mój plan będzie kompletny. Jesteś gotów?",
  ["data.otservbr.global.npc.vascalir.L168.1541"] = "Witaj z powrotem, |PLAYERNAME|! Ale - tak szybko? Proszę, znajdź gniazdo os w północno-zachodnim rejonie Rookgaard i użyj fiolki, którą ci dałem, na ich martwym ciele. A może zgubiłeś fiolkę?",
  ["data.otservbr.global.npc.vascalir.L171.1542"] = "Witaj z powrotem, |PLAYERNAME|! Udało ci się przynieść trochę jadu os?",
  ["data.otservbr.global.npc.vascalir.L174.1543"] = "Witaj z powrotem, |PLAYERNAME|! Masz teraz dość miejsca na tę mosiężną tarczę?",
  ["data.otservbr.global.npc.vascalir.L177.1544"] = "|PLAYERNAME|, nadszedł czas naszego triumfu. Jesteś gotów raz na zawsze pokonać Kraknaknorka?",
  ["data.otservbr.global.npc.vascalir.L184.1545"] = "|PLAYERNAME|! Wróciłeś! I jesteś cały we krwi orków... to może znaczyć tylko jedno... udało ci się zabić Kraknaknorka?",
  ["data.otservbr.global.npc.vascalir.L81.1520"] = "Witaj, poszukiwaczu przygód |PLAYERNAME|. To ciężkie czasy dla Rookgaard... przyszedłeś pomóc w naszej {mission}?",
  ["data.otservbr.global.npc.vascalir.L84.1521"] = "Pozdrowienia, |PLAYERNAME|. Twoje zadanie wciąż nie jest ukończone - pamiętasz wszystko, co musisz zrobić?",
  ["data.otservbr.global.npc.vascalir.L87.1522"] = "Pozdrowienia, |PLAYERNAME|. Słyszałem głośne dudnienie z dachu - mam nadzieję, że kamienie nie spadły ci na stopy. Załadowałeś co najmniej dwie katapulty?",
  ["data.otservbr.global.npc.vascalir.L90.1523"] = "Pozdrowienia, |PLAYERNAME|. Właściwie mam dla ciebie jeszcze trochę wyposażenia, ale najpierw chcę zobaczyć, jak walczysz. Walczyłeś już wcześniej, prawda?",
  ["data.otservbr.global.npc.vascalir.L93.1524"] = "Witaj z powrotem, |PLAYERNAME|. Skończyłeś z 5 szczurami, które kazałem ci zabić?",
  ["data.otservbr.global.npc.vascalir.L938.1546"] = "Żegnaj.",
  ["data.otservbr.global.npc.vascalir.L939.1547"] = "Żegnaj.",
  ["data.otservbr.global.npc.vescu.L103.84"] = "Hej t-tam... wyglądasz na kogoś, kto lubi dobre {booze}.",
  ["data.otservbr.global.npc.vescu.L196.85"] = "C-czas na kolejne p-piwo. <hik>",
  ["data.otservbr.global.npc.vescu.L197.86"] = "O, dwa t-trolle. Hellooo, małe trolliki. <hik>",
  ["data.otservbr.global.npc.virgil.L76.212"] = "Tak? Co mogę dla ciebie zrobić, |PLAYERNAME|? Może sprawy bankowe?",
  ["data.otservbr.global.npc.virgil.L77.213"] = "Miłego dnia.",
  ["data.otservbr.global.npc.virgil.L78.214"] = "Miłego dnia.",
  ["data.otservbr.global.npc.walter.jaeger.L294.1181"] = "Upewnij się, że masz wolne miejsca w skrzynce sklepowej.",
  ["data.otservbr.global.npc.walter.jaeger.L485.1182"] = "Udanych łowów! Mogę zaoferować ci świetne {rewards} za ukończenie zadań łowieckich! Dodatkowo mogę powiedzieć, ile punktów zadań łowieckich (HTP) aktualnie {have} i ile już {spent}.",
  ["data.otservbr.global.npc.walter.jaeger.L486.1183"] = "Poluj dalej!",
  ["data.otservbr.global.npc.walter.jaeger.L487.1184"] = "Poluj dalej!",
  ["data.otservbr.global.npc.walter.the.guard.L88.164"] = "NIECH ŻYJE KRÓL!",
  ["data.otservbr.global.npc.wentworth.L387.330"] = "Tak? Co mogę dla ciebie zrobić, |PLAYERNAME|? Może sprawy bankowe?",
  ["data.otservbr.global.npc.wentworth.L388.331"] = "Miłego dnia.",
  ["data.otservbr.global.npc.wentworth.L389.332"] = "Miłego dnia.",
  ["data.otservbr.global.npc.willard.L86.1037"] = "Pozdrowienia i niech Banor będzie z tobą, |PLAYERNAME|! Może zainteresuje cię {trade} bronią, amunicją lub pancerzem?",
  ["data.otservbr.global.npc.willard.L87.1038"] = "Żegnaj, |PLAYERNAME|.",
  ["data.otservbr.global.npc.willard.L88.1039"] = "Żegnaj, |PLAYERNAME|.",
  ["data.otservbr.global.npc.willard.L89.1040"] = "Oczywiście, przeglądaj moje towary. Jeśli interesuje cię tylko wyposażenie {distance}, daj znać.",
  ["data.otservbr.global.npc.willie.L283.1021"] = "Ta, spadaj!",
  ["data.otservbr.global.npc.willie.L284.1022"] = "Ta, pa |PLAYERNAME|.",
  ["data.otservbr.global.npc.willie.L285.1023"] = "No, dobrze się przyjrzyj.",
  ["data.otservbr.global.npc.willie.L286.1024"] = "[PL] Hiho |PLAYERNAME|. I hope you're here to {trade}.",
  ["data.otservbr.global.npc.woblin.L115.869"] = "Witaj, człowieku!",
  ["data.otservbr.global.npc.wyda.L132.1254"] = "Co? Zwykły śmiertelnik do mnie mówi? Zabawne.",
  ["data.otservbr.global.npc.wyrdin.L154.1122"] = "Witaj, co cię tu sprowadza?",
  ["data.otservbr.global.npc.wyrdin.L155.1123"] = "Powodzenia w podróżach, |PLAYERNAME|.",
  ["data.otservbr.global.npc.xelvar.L124.850"] = "Pozdrowienia. Interesują cię przygody?",
  ["data.otservbr.global.npc.xodet.L175.345"] = "Oczywiście, przejrzyj moje towary. A może chcesz zobaczyć tylko",
  ["data.otservbr.global.npc.xodet.L176.346"] = "Do widzenia i zapraszam ponownie.",
  ["data.otservbr.global.npc.xodet.L177.347"] = "Do widzenia i zapraszam ponownie.",
  ["data.otservbr.global.npc.xorlosh.L91.605"] = "Do zobaczenia, przyjacielu.",
  ["data.otservbr.global.npc.xorlosh.L92.606"] = "Do zobaczenia, przyjacielu.",
  ["data.otservbr.global.npc.xorlosh.L93.607"] = "Kim jesteś? Jesteś geniuszem mechaniki? Nie wyglądasz.",
  ["data.otservbr.global.npc.yaman.L167.634"] = "Żegnaj, człowieku.",
  ["data.otservbr.global.npc.yaman.L168.635"] = "Żegnaj, człowieku.",
  ["data.otservbr.global.npc.yaman.L169.636"] = "Do usług, przejrzyj moje towary.",
  ["data.otservbr.global.npc.yasir.L830.924"] = "[PL] Si, jema ze harun. <waves>",
  ["data.otservbr.global.npc.yberius.L169.1364"] = "Witaj, młody |PLAYERNAME|! Jeśli jesteś ciężko ranny lub zatruty, mogę cię za darmo {heal}.",
  ["data.otservbr.global.npc.yberius.L170.1365"] = "Pamiętaj: jeśli jesteś ciężko ranny lub zatruty, mogę cię uleczyć za darmo.",
  ["data.otservbr.global.npc.yberius.L171.1366"] = "Niech bogowie ci błogosławią, |PLAYERNAME|!",
  ["data.otservbr.global.npc.yoem.L61.188"] = "Witaj |PLAYERNAME|! Potrzebujesz wyposażenia do domu?",
  ["data.otservbr.global.npc.yoem.L62.189"] = "Spójrz. Większość mebli jest w poręcznych zestawach. Użyj ich w domu, aby złożyć meble. Chcesz zobaczyć tylko określony {type} mebli?",
  ["data.otservbr.global.npc.yonan.L137.684"] = "Jak mogę pomóc?",
  ["data.otservbr.global.npc.yonan.L140.685"] = "Jak mogę pomóc?",
  ["data.otservbr.global.npc.yonan.L143.686"] = "Jak mogę pomóc?",
  ["data.otservbr.global.npc.yonan.L216.687"] = "No to cześć.",
  ["data.otservbr.global.npc.zalamon.L421.1289"] = "Niewielu podróżnikzz tych dniazz. Mam nadzieję, że przynosisz dobre wieścizz.",
  ["data.otservbr.global.npc.zarifan.L89.1262"] = "... ... cześć...magiczne... słowa?",
  ["data.otservbr.global.npc.zebron.L134.469"] = "[PL] Greetings, high roller. So you care for a game, |PLAYERNAME|?",
  ["data.otservbr.global.npc.zebron.L135.470"] = "Hej, nie możesz wyjść. Szczęście się do ciebie uśmiecha. Czuję to!",
  ["data.otservbr.global.npc.zebron.L136.471"] = "Hej, nie możesz wyjść, |PLAYERNAME|. Szczęście się do ciebie uśmiecha. Czuję to!",
  ["data.otservbr.global.npc.zedrulon.the.fallen.L148.50"] = "Witaj, młody |PLAYERNAME|! Jeśli jesteś ciężko ranny lub zatruty, mogę cię za darmo {heal}.",
  ["data.otservbr.global.npc.zedrulon.the.fallen.L149.51"] = "Pamiętaj: jeśli jesteś ciężko ranny lub zatruty, mogę cię uleczyć za darmo.",
  ["data.otservbr.global.npc.zedrulon.the.fallen.L150.52"] = "Niech bogowie ci błogosławią, |PLAYERNAME|!",
  ["data.otservbr.global.npc.zerbrus.L210.7"] = "Hm...",
  ["data.otservbr.global.npc.zirella.L180.497"] = "[PL] Good bye |PLAYERNAME|, may Uman bless you!.",
  ["data.otservbr.global.npc.zirella.L181.498"] = "Do widzenia, podróżniku, uważaj na siebie.",
  ["data.otservbr.global.npc.zirella.L67.488"] = "Och, niebiosa musiały cię zesłać! Czy mógłbyś mi pomóc z {quest}?",
  ["data.otservbr.global.npc.zirella.L70.489"] = "Witaj z powrotem, kochanie... co do tego drewna opałowego, czy możesz mi {help}?",
  ["data.otservbr.global.npc.zirella.L73.490"] = "Witaj z powrotem, kochanie... co do {dead trees}, pozwól, że wyjaśnię to trochę bardziej, {yes}?",
  ["data.otservbr.global.npc.zirella.L76.491"] = "Witaj z powrotem, kochanie... co do {branches}, pozwól, że wyjaśnię to trochę bardziej, {yes}?",
  ["data.otservbr.global.npc.zirella.L79.492"] = "Witaj z powrotem, kochanie... co do {pushing}, pozwól, że wyjaśnię to trochę bardziej, {yes}?",
  ["data.otservbr.global.npc.zirella.L82.493"] = "Witaj z powrotem, kochanie... co do {cart}, pozwól, że wyjaśnię to trochę bardziej, {yes}?",
  ["data.otservbr.global.npc.zirella.L85.494"] = "Och, kochanie, jest jakiś problem z questem? Mam to znowu {explain}?",
  ["data.otservbr.global.npc.zirella.L88.495"] = "Dobrze, dziękuję kochanie! Tego wystarczy, by rozgrzać mój piec. Och, i pewnie czekasz na nagrodę, {yes}?",
  ["data.otservbr.global.npc.zirella.L91.496"] = "Och, witaj ponownie, drogi Isleth Eagonst! Przyszedłeś na małą pogawędkę? Użyj ponownie podświetlonych {keywords}, aby wybrać {topic}.",
  ["data.otservbr.global.npc.ziyad.L100.872"] = "Ach, wiatr przywiał kolejnego gościa. Witaj, drogi gościu. Szukasz {passage} na moim dywanie?",
  ["data.otservbr.global.npc.ziyad.L101.873"] = "Do widzenia. Poleć nas, jeśli byłeś zadowolony z naszej obsługi.",
  ["data.otservbr.global.npc.ziyad.L102.874"] = "W takim razie do widzenia.",
  ["data.otservbr.global.npc.zizzle.L114.1235"] = "Ach, nasi ludzcy {alliez} wreszcie przybyli! Już obawiałem się, że siły cesarza was dopadły. Wasza wytrzymałość i waleczność są imponujące.",
  ["data.otservbr.global.npc.zlak.L103.716"] = "Pozoztaw mnie w spokoju.",
  ["data.otservbr.global.npc.znozel.L71.200"] = "Tak? Co mogę dla ciebie zrobić, |PLAYERNAME|? Może sprawy bankowe?",
  ["data.otservbr.global.npc.znozel.L72.201"] = "Miłego dnia.",
  ["data.otservbr.global.npc.znozel.L73.202"] = "Miłego dnia.",
  ["data.otservbr.global.npc.zoltan.L113.593"] = "Witaj |PLAYERNAME|, uczniu sztuk tajemnych. Uczę najpotężniejszych dostępnych {spells}.",
  ["data.otservbr.global.npc.zoltan.L114.594"] = "Używaj swojej wiedzy mądrze, |PLAYERNAME|.",
  ["data.otservbr.global.npc.zora.L82.1328"] = "Och, wejdź proszę, |PLAYERNAME|. Co mogę dla ciebie zrobić? Jeśli potrzebujesz sprzętu na wyprawę, poproś o {trade}.",
  ["data.otservbr.global.npc.zora.L83.1329"] = "Do widzenia, |PLAYERNAME|.",
  ["data.otservbr.global.npc.zora.L84.1330"] = "Do widzenia, |PLAYERNAME|.",
  ["data.otservbr.global.npc.zora.L85.1331"] = "Oczywiście, przejrzyj moje towary. {Footballs} trzeba kupić osobno.",
  ["data.otservbr.global.npc.ztiss.L98.98"] = "Witaj mój... {guezt}.",
  ["data.otservbr.global.npc.zumtah.L141.1448"] = "Kolejny gość w tej ciasnej, przytulnej, spokojnej krainie, idealnej poza jednym {exit}. Muhaha.",
  ["data.otservbr.global.npc.zumtah.L142.1449"] = "Muhahaha!",
  ["data.otservbr.global.scripts.actions.dawnport.vocation.door.L34.2372"] = "Otwórz skrzynię i weź swój ekwipunek, młody.",
  ["data.otservbr.global.scripts.actions.dawnport.vocation.door.L36.2373"] = "Drzwi wydają się zapieczętowane przed nieproszonymi intruzami.",
  ["data.otservbr.global.scripts.actions.object.golden.outfit.display.L32.2353"] = "Aby z niego skorzystać, potrzebujesz pełnego złotego stroju.",
  ["data.otservbr.global.scripts.actions.object.imbuement.shrine.L5.2354"] = "Nie zebrałeś wystarczającej wiedzy od starożytnych Shaperów. Odwiedź świątynię Shaperów w Thais, aby uzyskać pomoc.",
  ["data.otservbr.global.scripts.actions.object.imbuement.shrine.L9.2355"] = "Możesz użyć świątyni tylko na prawidłowym przedmiocie.",
  ["data.otservbr.global.scripts.actions.object.wz789.entrance.L16.2356"] = "Potrzebujesz poziomu 250, aby wejść.",
  ["data.otservbr.global.scripts.actions.other.construction.kits.L123.2359"] = "Najpierw połóż zestaw konstrukcyjny na podłodze.",
  ["data.otservbr.global.scripts.actions.other.construction.kits.L125.2360"] = "Możesz to zbudować tylko wewnątrz domu.",
  ["data.otservbr.global.scripts.actions.other.fishing.L41.2361"] = "Nie jesteś właścicielem.",
  ["data.otservbr.global.scripts.actions.other.fishing.L89.2362"] = "Z potężnym pluskiem wyciągasz z wody ogromną rybę.",
  ["data.otservbr.global.scripts.actions.other.fluids.L106.2365"] = "To jest puste.",
  ["data.otservbr.global.scripts.actions.other.fluids.L112.2366"] = "Potrzebujesz wody.",
  ["data.otservbr.global.scripts.actions.other.fluids.L119.2367"] = "To jest puste.",
  ["data.otservbr.global.scripts.actions.other.fluids.L155.2368"] = "To jest puste.",
  ["data.otservbr.global.scripts.actions.other.gems.L150.2371"] = "Coś dzieje się na środku pomieszczenia...",
  ["data.otservbr.global.scripts.actions.other.gems.L91.2370"] = "Słyszysz *klik*. Możesz teraz podnieść płytkę podłogową i odkryć tajny schowek. Leży w nim maska z kości słoniowej.",
  ["data.otservbr.global.scripts.actions.other.kits.L26.2363"] = "Możesz to zbudować tylko wewnątrz domu.",
  ["data.otservbr.global.scripts.actions.other.mechanical.fishing.L19.2358"] = "Nie jesteś właścicielem.",
  ["data.otservbr.global.scripts.actions.other.music.L57.2364"] = "W tajemniczy sposób z fletni Pana spada kilka kolorowych nut. - Pośpiesz się, szybko znikną.",
  ["data.otservbr.global.scripts.actions.other.others.quest.system1.L179.2387"] = "Znalazłeś",
  ["data.otservbr.global.scripts.actions.other.others.quest.system1.L63.2386"] = "To",
  ["data.otservbr.global.scripts.actions.other.others.quest.system2.L368.2384"] = "To",
  ["data.otservbr.global.scripts.actions.other.others.quest.system2.L471.2385"] = "Znalazłeś",
  ["data.otservbr.global.scripts.actions.other.rafzane.elevator.L84.2369"] = "Aby skorzystać z windy, wejdź do środka.",
  ["data.otservbr.global.scripts.actions.other.special.firework.rocket.L139.2357"] = "Nie możesz użyć tego przedmiotu w kontenerze.",
  ["data.otservbr.global.scripts.actions.rookgaard.chest.L10.2375"] = "Znalazłeś drewniany miecz.",
  ["data.otservbr.global.scripts.actions.rookgaard.chest.L5.2374"] = "Skrzynia jest pusta.",
  ["data.otservbr.global.scripts.actions.rookgaard.goblin.temple.quest.L25.2376"] = "Znalazłeś torbę.",
  ["data.otservbr.global.scripts.actions.rookgaard.goblin.temple.quest.L59.2377"] = "Znalazłeś torbę.",
  ["data.otservbr.global.scripts.actions.rookgaard.rapier.quest.L8.2378"] = "Znalazłeś rapier.",
  ["data.otservbr.global.scripts.actions.roshamuul.prison.golden.L29.2388"] = "Potrzebujesz 5 graczy, aby walczyć z tym bossem.",
  ["data.otservbr.global.scripts.actions.roshamuul.prison.golden.L37.2389"] = "Ktoś walczy z bossem! Musisz chwilę poczekać.",
  ["data.otservbr.global.scripts.actions.roshamuul.prison.golden.L49.2390"] = "W ostatnim czasie walczyłeś już z tym bossem",
  ["data.otservbr.global.scripts.actions.roshamuul.prison.keys.L68.2391"] = "Wszedłeś do starożytnej demonicznej celi więziennej!",
  ["data.otservbr.global.scripts.actions.roshamuul.prison.keys.L69.2392"] = "Masz piętnaście minut, aby zabić i ograbić tego bossa, inaczej stracisz tę szansę.",
  ["data.otservbr.global.scripts.actions.system.quest.reward.common.L131.2379"] = "You have found a",
  ["data.otservbr.global.scripts.actions.system.quest.reward.common.L175.2380"] = "To",
  ["data.otservbr.global.scripts.actions.system.quest.reward.common.L179.2381"] = "To",
