  ["data.otservbr.global.scripts.actions.system.quest.reward.common.L188.2383"] = "To",
  ["data.otservbr.global.scripts.actions.tools.hammer.L87.2349"] = "Naprawiłeś tę zniszczoną ścianę.",
  ["data.otservbr.global.scripts.actions.tools.hammer.L91.2350"] = "Naprawiłeś już dziś wiele zniszczonych ścian.",
  ["data.otservbr.global.scripts.actions.tools.lock.pick.L12.2351"] = "Twój wytrych otworzył tę skrzynię!",
  ["data.otservbr.global.scripts.actions.tools.lock.pick.L16.2352"] = "Twój wytrych się złamał.",
  ["data.otservbr.global.scripts.creaturescripts.customs.freequests.L377.2347"] = "Dodano ukończone darmowe questy.",
  ["data.otservbr.global.scripts.creaturescripts.customs.freequests.L404.2348"] = "Dodano darmowe questy dostępu do twojej postaci.",
  ["data.otservbr.global.scripts.creaturescripts.customs.reward.exercise.L7.2346"] = "Możesz odebrać broń treningową komendą !reward",
  ["data.otservbr.global.scripts.globalevents.others.check.mount.L28.2345"] = "Twoja umowa na konia wygasła i wrócił on do stacji koni.",
  ["data.otservbr.global.scripts.lib.register.actions.L1054.1640"] = "Ten stół jest zrobiony z kilku starych drzwi. Jedne z nich mają wyraźny, ozdobny zamek. Może dałoby się go podważyć narzędziem.",
  ["data.otservbr.global.scripts.lib.register.actions.L1057.1641"] = "Już usunąłeś stary zamek.",
  ["data.otservbr.global.scripts.lib.register.actions.L1165.1642"] = "Mielisz",
  ["data.otservbr.global.scripts.lib.register.actions.L1174.1643"] = "Mielisz",
  ["data.otservbr.global.scripts.lib.register.actions.L329.1625"] = "Pomyślnie użyłeś liny, aby wydostać się z dołu. Gratulacje! Teraz idź dalej na wschód.",
  ["data.otservbr.global.scripts.lib.register.actions.L364.1626"] = "Znalazłeś starożytny amulet. Pokrywają go dziwne ryty. Może Morris zdoła je odczytać.",
  ["data.otservbr.global.scripts.lib.register.actions.L367.1627"] = "Wykopujesz piasek i muszle morskie.",
  ["data.otservbr.global.scripts.lib.register.actions.L370.1628"] = "Wykopujesz kilka robaków. Jesteś jednak pewien, że gdzieś tutaj znajdziesz amulet.",
  ["data.otservbr.global.scripts.lib.register.actions.L389.1629"] = "Znalazłeś małą smoczą łzę. Szybko chowasz ją do kieszeni.",
  ["data.otservbr.global.scripts.lib.register.actions.L395.1630"] = "Nie znajdujesz nic interesującego.",
  ["data.otservbr.global.scripts.lib.register.actions.L430.1631"] = "Wykopałeś dół! Wejdź na niego, póki jest otwarty, aby wskoczyć do leśnej jaskini.",
  ["data.otservbr.global.scripts.lib.register.actions.L438.1632"] = "Znalazłeś kawałek zwoju. Szybko to schowasz.",
  ["data.otservbr.global.scripts.lib.register.actions.L443.1633"] = "Pojawia się rozdarty fragment zwoju. Prawdopodobnie ogryziony przez szczury.",
  ["data.otservbr.global.scripts.lib.register.actions.L484.1634"] = "Wykopałeś A",
  ["data.otservbr.global.scripts.lib.register.actions.L539.1635"] = "Ten stół jest zrobiony z kilku starych drzwi. Jedne z nich mają wyraźny, ozdobny zamek. Może dałoby się go podważyć narzędziem.",
  ["data.otservbr.global.scripts.lib.register.actions.L542.1636"] = "Już usunąłeś stary zamek.",
  ["data.otservbr.global.scripts.lib.register.actions.L769.1637"] = "Nie możesz usunąć tej sterty, ponieważ obecnie podtrzymuje tunel.",
  ["data.otservbr.global.scripts.lib.register.actions.L827.1638"] = "Kruszenie kamienia daje trochę drobnego żwiru.",
  ["data.otservbr.global.scripts.lib.register.actions.L831.1639"] = "Kruszenie kamienia nie daje nic poza nieco drobniejszą, ale nadal bezużyteczną gumą.",
  ["data.otservbr.global.scripts.movements.oramond.seacrest.L12.2329"] = "Wchodzisz na teren Seacrest.",
  ["data.otservbr.global.scripts.movements.oramond.seacrest.L15.2330"] = "Aby nurkować, musisz mieć na sobie hełm do podwodnej eksploracji.",
  ["data.otservbr.global.scripts.movements.others.dawnport.tiles.L124.2337"] = "Witamy w Dawnport! Rozejrzyj się i odkrywaj na własną rękę albo porozmawiaj z Inigo, jeśli potrzebujesz wskazówek.",
  ["data.otservbr.global.scripts.movements.others.dawnport.tiles.L148.2338"] = "[PL] <krrk> <krrrrrk> You move away hurriedly.",
  ["data.otservbr.global.scripts.movements.others.dawnport.tiles.L165.2339"] = "Aby chodzić po SCHODACH, użyj klawiszy strzałek na klawiaturze. Możesz ich też używać do poruszania się ogólnie.",
  ["data.otservbr.global.scripts.movements.others.dawnport.tiles.L239.2340"] = "Zostałeś uleczony.",
  ["data.otservbr.global.scripts.movements.others.dawnport.tiles.L32.2331"] = "Powinieneś sprawdzić skrzynię po swój",
  ["data.otservbr.global.scripts.movements.others.dawnport.tiles.L36.2332"] = "Powinieneś teraz wyruszyć na Mainland. Idź w lewo, aby dotrzeć do statku.",
  ["data.otservbr.global.scripts.movements.others.dawnport.tiles.L41.2333"] = "Nie masz odpowiedniej profesji, aby wejść do tego pomieszczenia.",
  ["data.otservbr.global.scripts.movements.others.dawnport.tiles.L48.2334"] = "Wybrałeś swoją profesję. Nie możesz wrócić.",
  ["data.otservbr.global.scripts.movements.others.dawnport.tiles.L76.2335"] = "Nie możesz wejść na górę. Wybrałeś profesję i musisz teraz opuścić to miejsce, udając się na Mainland.",
  ["data.otservbr.global.scripts.movements.others.dawnport.tiles.L99.2336"] = "Użyj tych schodów, aby wejść do Posterunku Poszukiwaczy Przygód w Dawnport.",
  ["data.otservbr.global.scripts.movements.others.dawnport.vocation.trial.L155.2341"] = "Ponieważ pierwszy raz testujesz profesję, Gildia wyposażyła cię w sprzęt.",
  ["data.otservbr.global.scripts.movements.rookgaard.level.bridge.L17.2343"] = "Aby przejść, potrzebujesz co najmniej poziomu 2.",
  ["data.otservbr.global.scripts.movements.rookgaard.rook.village.L10.2342"] = "Nie masz już tam nic do roboty.",
