  ["data.otservbr.global.scripts.quests.adventures.of.galthen.actions.yselda.shortcut.L13.1754"] = "Ten korzeń zdaje się grubieć i oplatać, gdy tylko próbujesz go chwycić.",
  ["data.otservbr.global.scripts.quests.chayenne.realm.actions.lever.L11.1689"] = "Nie masz magicznego klucza Chayenne.",
  ["data.otservbr.global.scripts.quests.chayenne.realm.actions.lever.L6.1688"] = "Musisz odczekać kilka minut, aby użyć tego ponownie.",
  ["data.otservbr.global.scripts.quests.chayenne.realm.actions.reward.L14.1686"] = "Znalazłeś plażowy plecak.",
  ["data.otservbr.global.scripts.quests.chayenne.realm.actions.reward.L16.1687"] = "Odebrałeś już swoją nagrodę.",
  ["data.otservbr.global.scripts.quests.chayenne.realm.movements.enter.realm.L14.1683"] = "Wkraczasz do krainy snów.",
  ["data.otservbr.global.scripts.quests.chayenne.realm.movements.enter.realm.L16.1684"] = "Nie masz poziomu 40+ albo brakuje ci magicznego klucza Chayenne.",
  ["data.otservbr.global.scripts.quests.chayenne.realm.movements.enter.realm.L23.1685"] = "Żegnaj, podróżniku snów...",
  ["data.otservbr.global.scripts.quests.children.of.the.revolution.actions.mission3.chest.L7.2155"] = "Znalazłeś fiolkę trucizny.",
  ["data.otservbr.global.scripts.quests.children.of.the.revolution.actions.mission3.chest.L9.2156"] = "Skrzynia jest pusta.",
  ["data.otservbr.global.scripts.quests.children.of.the.revolution.actions.zalamon.door.L12.2154"] = "Drzwi wydają się zapieczętowane przed nieproszonymi intruzami.",
  ["data.otservbr.global.scripts.quests.cults.of.tibia.actions.analyser.L20.2105"] = "Dobra robota! Woda została przeanalizowana.",
  ["data.otservbr.global.scripts.quests.cults.of.tibia.actions.counter.agent.L37.2085"] = "Burza piaskowa zniszczyła niemal wszystkie filary. Działanie odczynnika zadziałało inaczej niż oczekiwano.",
  ["data.otservbr.global.scripts.quests.cults.of.tibia.actions.counter.agent.L38.2086"] = "Burza piaskowa nie tylko zniszczyła oazę, ale też odsłoniła kilka płyt i dźwignię.",
  ["data.otservbr.global.scripts.quests.cults.of.tibia.actions.crate.L11.2083"] = "Wziąłeś już lupę.",
  ["data.otservbr.global.scripts.quests.cults.of.tibia.actions.crate.L13.2084"] = "Ta skrzynia należy do Angelo. Powinieneś z nim porozmawiać, zanim coś z niej wyjmiesz.",
  ["data.otservbr.global.scripts.quests.cults.of.tibia.actions.crate.L7.2082"] = "Świetnie! Wziąłeś z tej skrzyni wspaniałą lupę.",
  ["data.otservbr.global.scripts.quests.cults.of.tibia.actions.document.L10.2103"] = "Za niewielką opłatą odzyskasz ją z powrotem. Po więcej informacji porozmawiaj z Iwarem w Kazordoon.",
  ["data.otservbr.global.scripts.quests.cults.of.tibia.actions.document.L11.2104"] = "Zapytaj go: Czy kot ugryzł cię w język?",
  ["data.otservbr.global.scripts.quests.cults.of.tibia.actions.document.L7.2100"] = "Drogi kustoszu, to niedawno otwarte muzeum to naprawdę świetne miejsce.",
  ["data.otservbr.global.scripts.quests.cults.of.tibia.actions.document.L8.2101"] = "Ale zaraz! Co z pustą przestrzenią przed tobą? Co za szkoda!",
  ["data.otservbr.global.scripts.quests.cults.of.tibia.actions.document.L9.2102"] = "Wygląda na to, że ktoś usunął jeden z pięknych obrazów. Ale no dalej! Ty masz pieniądze, a my ich potrzebujemy.",
  ["data.otservbr.global.scripts.quests.cults.of.tibia.actions.last.object.L23.2096"] = "Dziwny symbol na tylnej ścianie gwałtownie świeci.",
  ["data.otservbr.global.scripts.quests.cults.of.tibia.actions.last.object.L24.2097"] = "Obiekt kultu leży spokojnie. Niebezpieczny obszar wokół niego niemal całkowicie zanikł.",
  ["data.otservbr.global.scripts.quests.cults.of.tibia.actions.last.object.L25.2098"] = "Gdy wyciągasz rękę, by dotknąć obiektu kultu, ze czaszki wybucha fala energii. Udało ci się odpędzić jej moc.",
  ["data.otservbr.global.scripts.quests.cults.of.tibia.actions.magnifier.L19.2122"] = "Nic szczególnego. Ten obraz wygląda na autentyczny.",
  ["data.otservbr.global.scripts.quests.cults.of.tibia.actions.magnifier.L24.2123"] = "This is it. It looks like it was painted by a child!",
  ["data.otservbr.global.scripts.quests.cults.of.tibia.actions.misguided.L62.2109"] = "Paraliżujesz napastnika, a amulet ujawnia prawdziwą twarz stworzenia stojącego za opętaniem tej zagubionej istoty.",
  ["data.otservbr.global.scripts.quests.cults.of.tibia.actions.torch.L18.2116"] = "Słyszysz głośny zgrzyt niedaleko siebie. Coś bardzo ciężkiego najwyraźniej się poruszyło.",
  ["data.otservbr.global.scripts.quests.cults.of.tibia.movements.begin.task.L36.2106"] = "Amulet parzy twoją skórę. Teraz łaknie energii, zbierz jej dużą ilość jak najszybciej, by go naładować.",
  ["data.otservbr.global.scripts.quests.cults.of.tibia.movements.check.oasis.L10.2108"] = "Znalazłeś urokliwą oazę z zieloną roślinnością i soczystymi owocami. Tego się nie spodziewałeś.",
  ["data.otservbr.global.scripts.quests.cults.of.tibia.movements.energy.fence.L31.2117"] = "Jako naczynie wiążące moc zwiędłych dusz przechodzisz przez magiczną barierę.",
  ["data.otservbr.global.scripts.quests.cults.of.tibia.movements.energy.fence.L35.2118"] = "Połączone moce gnijących dusz krążących po tych korytarzach mogą pomóc przełamać tę barierę, potrzebują jedynie naczynia, które je zwiąże.",
  ["data.otservbr.global.scripts.quests.cults.of.tibia.movements.energy.fence.L39.2119"] = "Jako naczynie wiążące moc zwiędłych dusz przechodzisz przez magiczną barierę.",
  ["data.otservbr.global.scripts.quests.cults.of.tibia.movements.energy.fence.L43.2120"] = "Połączone moce gnijących dusz krążących po tych korytarzach mogą pomóc przełamać tę barierę, potrzebują jedynie naczynia, które je zwiąże.",
  ["data.otservbr.global.scripts.quests.cults.of.tibia.movements.energy.fence.L49.2121"] = "Gdy przekraczasz próg wewnętrznego sanktuarium kultu Misguided, czujesz wokół siebie upiorną obecność.",
  ["data.otservbr.global.scripts.quests.cults.of.tibia.movements.ice.L93.2099"] = "Gdy opuszczasz lodową jaskinię, do twojego ciała wraca odrobina ciepła.",
  ["data.otservbr.global.scripts.quests.cults.of.tibia.movements.ice.death.L62.2087"] = "Zostałeś zabity przez coś złego i innych.",
  ["data.otservbr.global.scripts.quests.cults.of.tibia.movements.ice.death.L63.2088"] = "Nadal jesteś błogosławiony Mądrością Samotności, Iskrą Feniksa, Ogniem Słońc, Duchową Tarczą, Uściskiem Tibia, Sercem Góry, Krwią Góry i Zwrotem Losu.",
  ["data.otservbr.global.scripts.quests.cults.of.tibia.movements.ice.death.L64.2089"] = "Straciłeś 0 doświadczenia i 0.00% wszystkich umiejętności.",
  ["data.otservbr.global.scripts.quests.cults.of.tibia.movements.ice.death.L65.2090"] = "Nie straciłeś żadnych przedmiotów.",
  ["data.otservbr.global.scripts.quests.cults.of.tibia.movements.ice.death.L68.2091"] = "Zimno niemal całkowicie ustąpiło z twojego ciała i robi ci się cieplej. Musisz odnowić wszystkie przygotowania do oczyszczenia.",
  ["data.otservbr.global.scripts.quests.cults.of.tibia.movements.looktype.L15.2110"] = "Dzięki sile orka możesz przejść przez tę szczelinę.",
