  ["data.otservbr.global.scripts.quests.the.dream.courts.quest.actions.bookOnTable.L14.1855"] = "Ta książka opowiada o zaklęciu, które przyciąga jego użytkownika do najbardziej energetycznej istoty obok niego.",
