  ["data.otservbr.global.scripts.quests.the.gravedigger.of.drefia.actions.inscriptions.L13.2024"] = "Słowa zdają się trzepotać. Jedno słowo zostaje w twojej głowie: floating.",
  ["data.otservbr.global.scripts.quests.the.gravedigger.of.drefia.actions.inscriptions.L5.2022"] = "Słowa zdają się oddychać, dziwnie. Jedno słowo zostaje w twojej głowie: bronze.",
  ["data.otservbr.global.scripts.quests.the.gravedigger.of.drefia.actions.inscriptions.L9.2023"] = "Słowa lekko świecą. W twojej głowie utrwala się imię: Takesha Antishu.",
  ["data.otservbr.global.scripts.quests.the.gravedigger.of.drefia.actions.key1.L8.2026"] = "[PL] <swoosh> <oomph> <cough, cough>",
  ["data.otservbr.global.scripts.quests.the.gravedigger.of.drefia.actions.key2.L14.2016"] = "Wynoś się z mojego pokoju!",
  ["data.otservbr.global.scripts.quests.the.gravedigger.of.drefia.actions.key2.L9.2015"] = "Niewidzialna dłoń wciąga cię do środka.",
  ["data.otservbr.global.scripts.quests.the.gravedigger.of.drefia.actions.palanca.L6.2025"] = "<syk> <bąbelki>",
  ["data.otservbr.global.scripts.quests.the.gravedigger.of.drefia.actions.pyramids1.L17.2013"] = "<syk> <bąbelki>",
  ["data.otservbr.global.scripts.quests.the.gravedigger.of.drefia.actions.pyramids2.L18.2027"] = "<skrzyp> <pisk> <przeciągły pisk>",
  ["data.otservbr.global.scripts.quests.the.gravedigger.of.drefia.actions.pyramids2.L21.2028"] = "Misja została tu już ukończona!",
  ["data.otservbr.global.scripts.quests.the.gravedigger.of.drefia.actions.sacrifice.L7.2011"] = "Zwój spala się na pył. Magia drży. Dusza Omrabasa ucieka do dawnej kryjówki.",
  ["data.otservbr.global.scripts.quests.the.gravedigger.of.drefia.actions.scroll.L6.2017"] = "Ktoś zostawił kartkę. Widnieje na niej: Szukasz zwoju? Znajdź mnie. Weź schody obok studentów. Dorm.",
  ["data.otservbr.global.scripts.quests.the.gravedigger.of.drefia.actions.statue.L12.2018"] = "<BOOOOOOOONGGGGGG> Przez podłogę przechodzi powolne pulsowanie, jak bicie krwi.",
  ["data.otservbr.global.scripts.quests.the.gravedigger.of.drefia.actions.tears.L9.2021"] = "Smocze łzy świecą i znikają. Stare moce zostały ułagodzone.",
  ["data.otservbr.global.scripts.quests.the.gravedigger.of.drefia.actions.tincture.L9.2010"] = "Rozbijasz fiolkę i rozlewasz krwawą nalewkę. Ołtarz został namaszczony.",
  ["data.otservbr.global.scripts.quests.the.gravedigger.of.drefia.movements.dormitory.teleport.L13.2007"] = "Powinieneś się pospieszyć, postaraj się nie zostawać tu dłużej niż kilka minut.",
  ["data.otservbr.global.scripts.quests.the.gravedigger.of.drefia.movements.dormitory.teleport.L16.2008"] = "Teleport jest dostępny tylko raz.",
  ["data.otservbr.global.scripts.quests.the.great.dragon.hunt.quest.actions.treasure.L22.1794"] = "Nie da się zabrać wszystkich skarbów stąd. Ale wybierasz",
  ["data.otservbr.global.scripts.quests.the.great.dragon.hunt.quest.actions.treasure.L40.1795"] = "Próbujesz zabrać skarb, ale słyszysz, że nadciągają kolejne smoki. Powinieneś zabić jeszcze kilka, zanim coś wybierzesz.",
  ["data.otservbr.global.scripts.quests.the.great.dragon.hunt.quest.actions.warrior.skeleton.L15.1793"] = "Martwy odkrywca jest pusty.",
  ["data.otservbr.global.scripts.quests.the.great.dragon.hunt.quest.actions.warrior.skeleton.L5.1792"] = "Odkryłeś szkielet zmarłego wojownika. Wygląda na to, że próbował polować na tutejsze smoki - i poległ.",
  ["data.otservbr.global.scripts.quests.the.hidden.city.of.beregar.actions.ore.wagon.L103.2158"] = "Nie masz jeszcze uprawnień, aby tego użyć.",
  ["data.otservbr.global.scripts.quests.the.hidden.city.of.beregar.actions.ore.wagon.L176.2159"] = "Jeszcze nie wiesz, jak tego użyć.",
  ["data.otservbr.global.scripts.quests.the.hidden.city.of.beregar.moviments.elevator.L23.2160"] = "Jeszcze nie wiesz, jak tego użyć.",
  ["data.otservbr.global.scripts.quests.the.hidden.city.of.beregar.moviments.ore.wagon.L11.2157"] = "Znalazłeś wejście do ukrytego miasta Beregar i możesz teraz korzystać z wagonu rud.",
  ["data.otservbr.global.scripts.quests.the.hunt.for.the.sea.serpent.actions.bait.L47.2241"] = "Najpierw powinieneś założyć nową przynętę.",
  ["data.otservbr.global.scripts.quests.the.hunt.for.the.sea.serpent.actions.bait.L49.2242"] = "Ups! Straciłeś to.",
  ["data.otservbr.global.scripts.quests.the.hunt.for.the.sea.serpent.actions.bait.L53.2243"] = "Widzisz wodę aż po horyzont. Ani śladu morskiego węża.",
  ["data.otservbr.global.scripts.quests.the.hunt.for.the.sea.serpent.actions.bait.L66.2244"] = "Ucieka! Powinieneś powiedzieć kapitanowi, żeby przyspieszył!",
  ["data.otservbr.global.scripts.quests.the.hunt.for.the.sea.serpent.actions.bait.L72.2245"] = "Pod powierzchnią widać wiele cieni. To musi być właściwe miejsce.",
  ["data.otservbr.global.scripts.quests.the.hunt.for.the.sea.serpent.movements.teleports.L26.2238"] = "Musisz założyć hełm głębin.",
  ["data.otservbr.global.scripts.quests.the.hunt.for.the.sea.serpent.movements.teleports.L31.2239"] = "Musisz założyć hełm głębin.",
  ["data.otservbr.global.scripts.quests.the.hunt.for.the.sea.serpent.movements.teleports.L36.2240"] = "Nie jesteś jeszcze we właściwym miejscu.",
  ["data.otservbr.global.scripts.quests.the.inquisition.quest.actions.rewards.L20.1770"] = "Znalazłeś",
  ["data.otservbr.global.scripts.quests.the.inquisition.quest.actions.rewards.L27.1771"] = "Skrzynia jest pusta.",
  ["data.otservbr.global.scripts.quests.the.inquisition.quest.actions.ungreez.door.L20.1772"] = "Drzwi wydają się zapieczętowane przed nieproszonymi intruzami.",
  ["data.otservbr.global.scripts.quests.the.lost.brother.movement.find.remains.L10.1984"] = "Potykasz się o stare kości. Coś wyryto tu w kamiennej ścianie: 'Tarun, mój bracie, miałeś rację. Ona jest zła.'",
  ["data.otservbr.global.scripts.quests.the.new.frontier.action.arena.L62.2164"] = "Już ukończyłeś tę walkę.",
  ["data.otservbr.global.scripts.quests.the.new.frontier.action.arena.L67.2165"] = "Arena jest już zajęta.",
  ["data.otservbr.global.scripts.quests.the.new.frontier.action.hidden.note.L9.2170"] = "Znalazłeś kawałek papieru.",
  ["data.otservbr.global.scripts.quests.the.new.frontier.action.outfit.L11.2166"] = "Zdobyłeś nowy outfit i możesz teraz opuścić pokój nagród!",
  ["data.otservbr.global.scripts.quests.the.new.frontier.action.outfit.L13.2167"] = "Już odebrałeś outfit, zapytaj Chraka o misję.",
  ["data.otservbr.global.scripts.quests.the.new.frontier.movement.jail.exit.L22.2168"] = "Nie masz dostępu do tego obszaru.",
  ["data.otservbr.global.scripts.quests.the.new.frontier.movement.minotaur.boss.L31.2169"] = "Nie masz dostępu do tego obszaru.",
  ["data.otservbr.global.scripts.quests.the.order.of.lion.action.drume.L106.1647"] = "Masz",
  ["data.otservbr.global.scripts.quests.the.order.of.lion.action.drume.L32.1646"] = "Twój czas dobiegł końca.",
  ["data.otservbr.global.scripts.quests.the.order.of.lion.creatureevent.commander.kills.L19.1645"] = "Przegrałeś potyczkę.",
  ["data.otservbr.global.scripts.quests.the.order.of.lion.moveevent.drume.entrance.L5.1644"] = "Brałeś udział w potyczce w ciągu ostatnich 10 godzin.",
  ["data.otservbr.global.scripts.quests.the.outlaw.camp.actions.the.outlaw.camp.quest.L24.1909"] = "Znalazłeś torbę.",
  ["data.otservbr.global.scripts.quests.the.paradox.tower.movement.sacrifice.skulls.L24.1751"] = "Jedno z toksycznych słonych mórz na Krailos znów niesie świeżą i czystą wodę. Zaopatrzenie ogrów w wodę jest na razie zapewnione.",
  ["data.otservbr.global.scripts.quests.the.pits.of.inferno.quest.movements.pumin.teleport.L15.2236"] = "Aby wejść do domeny Pumina, musisz uzyskać zgodę biurokratów.",
  ["data.otservbr.global.scripts.quests.the.postman.missions.quest.actions.waldos.posthorn.L6.2152"] = "Znalazłeś róg pocztowy Waldo.",
  ["data.otservbr.global.scripts.quests.the.postman.missions.quest.actions.waldos.posthorn.L8.2153"] = "Martwy człowiek jest pusty.",
  ["data.otservbr.global.scripts.quests.the.primal.ordeal.creaturescripts.magma.bubble.death.L17.2173"] = "Gratulacje ty otrzymaNie the Fire-Bojownik, wojownik, uczestnik walki Strój.",
  ["data.otservbr.global.scripts.quests.the.rookie.guard.mission02.defence.L100.1698"] = "Musisz poczekać kilka minut, zanim będziesz mógł podnieść nowy kamień.",
  ["data.otservbr.global.scripts.quests.the.rookie.guard.mission02.defence.L103.1699"] = "Nie potrzebujesz już kamieni. Obrona Rookgaard została wzmocniona.",
  ["data.otservbr.global.scripts.quests.the.rookie.guard.mission02.defence.L129.1700"] = "Ładujesz ciężki kamień na katapultę. Teraz weź kolejny kamień i znajdź pozostałą katapultę.",
  ["data.otservbr.global.scripts.quests.the.rookie.guard.mission02.defence.L131.1701"] = "Załadowałeś ostatni kamień na katapulty. Czas wracać do Vascalira.",
  ["data.otservbr.global.scripts.quests.the.rookie.guard.mission02.defence.L138.1702"] = "Załadowałeś już kamień na tę katapultę. Rozejrzyj się po innych dachach, aby znaleźć pozostałe katapulty.",
  ["data.otservbr.global.scripts.quests.the.rookie.guard.mission05.web.terror.L100.1727"] = "Wcierasz dziwny smar w ciało. Królowa pająków nie wyczuje cię przez około 2 minuty. Pośpiesz się!",
  ["data.otservbr.global.scripts.quests.the.rookie.guard.mission05.web.terror.L105.1728"] = "Masz już część pajęczyny królowej pająków. Nie ma potrzeby tam wracać.",
  ["data.otservbr.global.scripts.quests.the.rookie.guard.mission05.web.terror.L126.1729"] = "Nie wchodź do legowiska bez ochronnego smaru. Użyj jednego z kamieni na północy, aby stać się dla niej niewidzialnym.",
  ["data.otservbr.global.scripts.quests.the.rookie.guard.mission05.web.terror.L133.1730"] = "Masz już pajęczynę królowej pająków. Powinieneś wrócić do Vascalira i nie podejmować dalszego ryzyka.",
  ["data.otservbr.global.scripts.quests.the.rookie.guard.mission05.web.terror.L154.1731"] = "Zdobyłeś część pajęczyny królowej pająków. Wracaj szybko, zanim znów cię wyczuje!",
  ["data.otservbr.global.scripts.quests.the.rookie.guard.mission05.web.terror.L75.1726"] = "Nie masz tam czego szukać.",
  ["data.otservbr.global.scripts.quests.the.rookie.guard.mission06.run.like.wolf.L140.1691"] = "O nie... byłeś za wolny i wilki cię dogoniły. Możesz spróbować ponownie.",
  ["data.otservbr.global.scripts.quests.the.rookie.guard.mission06.run.like.wolf.L155.1692"] = "BIEEEEGNIIIIIIIIIIIIJ!",
  ["data.otservbr.global.scripts.quests.the.rookie.guard.mission06.run.like.wolf.L184.1693"] = "Znalazłeś",
  ["data.otservbr.global.scripts.quests.the.rookie.guard.mission06.run.like.wolf.L189.1694"] = "To",
  ["data.otservbr.global.scripts.quests.the.rookie.guard.mission06.run.like.wolf.L205.1695"] = "Masz skórę wojennego wilka - ale słyszysz za sobą przerażające wycie. Czas stąd znikać - SZYBKO!",
  ["data.otservbr.global.scripts.quests.the.rookie.guard.mission06.run.like.wolf.L230.1696"] = "Znalazłeś",
  ["data.otservbr.global.scripts.quests.the.rookie.guard.mission06.run.like.wolf.L234.1697"] = "To",
  ["data.otservbr.global.scripts.quests.the.rookie.guard.mission06.run.like.wolf.L72.1690"] = "Nie masz tam czego szukać.",
  ["data.otservbr.global.scripts.quests.the.rookie.guard.mission07.attack.L123.1741"] = "Przez ogień na tej arenie można przejść bez obrażeń. Otwórz skrzynię i uciekaj stąd!",
  ["data.otservbr.global.scripts.quests.the.rookie.guard.mission07.attack.L148.1742"] = "Znalazłeś",
  ["data.otservbr.global.scripts.quests.the.rookie.guard.mission07.attack.L152.1743"] = "To",
  ["data.otservbr.global.scripts.quests.the.rookie.guard.mission07.attack.L77.1739"] = "Kaszel tak cię dusi, że musiałeś wrócić na górę. Weź kilka głębokich oddechów i spróbuj ponownie.",
  ["data.otservbr.global.scripts.quests.the.rookie.guard.mission07.attack.L97.1740"] = "Ten ogień jest zbyt gorący, by przez niego przejść. Użyj runy destroy field na ogniu, aby osłabić płomienie!",
  ["data.otservbr.global.scripts.quests.the.rookie.guard.mission09.rock.troll.L118.1734"] = "Znalazłeś",
  ["data.otservbr.global.scripts.quests.the.rookie.guard.mission09.rock.troll.L122.1735"] = "To",
  ["data.otservbr.global.scripts.quests.the.rookie.guard.mission09.rock.troll.L159.1736"] = "To powinno osłabić belkę na tyle, że wkrótce się zawali.",
  ["data.otservbr.global.scripts.quests.the.rookie.guard.mission09.rock.troll.L161.1737"] = "To była ostatnia belka. Teraz uciekaj stąd, zanim jaskinia się zawali!",
  ["data.otservbr.global.scripts.quests.the.rookie.guard.mission09.rock.troll.L169.1738"] = "Już osłabiłeś tę belkę. Lepiej zostaw ją w spokoju, żeby nie zawaliła się, zanim stąd wyjdziesz.",
  ["data.otservbr.global.scripts.quests.the.rookie.guard.mission09.rock.troll.L74.1732"] = "Nie masz tam czego szukać.",
  ["data.otservbr.global.scripts.quests.the.rookie.guard.mission09.rock.troll.L77.1733"] = "Jaskinia się zawaliła. Schodzenie tam na dół nie jest już bezpieczne.",
  ["data.otservbr.global.scripts.quests.the.rookie.guard.mission10.tomb.raiding.L142.1747"] = "Znalazłeś",
  ["data.otservbr.global.scripts.quests.the.rookie.guard.mission10.tomb.raiding.L144.1748"] = "Znalazłeś",
  ["data.otservbr.global.scripts.quests.the.rookie.guard.mission10.tomb.raiding.L149.1749"] = "To",
  ["data.otservbr.global.scripts.quests.the.rookie.guard.mission10.tomb.raiding.L91.1745"] = "Znalazłeś",
  ["data.otservbr.global.scripts.quests.the.rookie.guard.mission10.tomb.raiding.L95.1746"] = "To",
  ["data.otservbr.global.scripts.quests.the.rookie.guard.mission11.sweet.poison.L59.1744"] = "Ostrożnie zbierasz trochę trucizny os. Zanieś to Vascalirowi.",
  ["data.otservbr.global.scripts.quests.the.rookie.guard.mission12.into.fortress.L178.1703"] = "Znalazłeś",
  ["data.otservbr.global.scripts.quests.the.rookie.guard.mission12.into.fortress.L183.1704"] = "To",
  ["data.otservbr.global.scripts.quests.the.rookie.guard.mission12.into.fortress.L209.1705"] = "Ogłuszasz niczego niepodejrzewającego orka. Użyj go, by przebrać się za orka!",
  ["data.otservbr.global.scripts.quests.the.rookie.guard.mission12.into.fortress.L217.1706"] = "Nie masz powodu robić czegoś tak podstępnego.",
  ["data.otservbr.global.scripts.quests.the.rookie.guard.mission12.into.fortress.L232.1707"] = "Wyglądasz prawie jak ork. Nie nabiorą się wszyscy orkowie, ale głupi strażnik przed fortecą powinien dać się oszukać.",
  ["data.otservbr.global.scripts.quests.the.rookie.guard.mission12.into.fortress.L277.1708"] = "To powinno wystarczyć jako odwrócenie uwagi, żebyś zakradł się do fortecy! Pośpiesz się!",
  ["data.otservbr.global.scripts.quests.the.rookie.guard.mission12.into.fortress.L310.1709"] = "Zatrułeś zupę Kraknaknorka. To powinno go bardzo osłabić. Czas znaleźć jego komnatę.",
  ["data.otservbr.global.scripts.quests.the.rookie.guard.mission12.into.fortress.L329.1710"] = "Berserker nie może cię teraz złapać - ale tylko przez 20 sekund. Musisz odciągnąć go od teleportera!",
  ["data.otservbr.global.scripts.quests.the.rookie.guard.mission12.into.fortress.L362.1711"] = "Dopóki orczy berserker jest blisko teleportera, nie możesz wejść.",
  ["data.otservbr.global.scripts.quests.the.rookie.guard.mission12.into.fortress.L370.1712"] = "Wchodzisz do legowiska Kraknaknorka.",
  ["data.otservbr.global.scripts.quests.the.rookie.guard.mission12.into.fortress.L483.1713"] = "Gdzieś tymczasowo zniknęła bariera energetyczna.",
  ["data.otservbr.global.scripts.quests.the.rookie.guard.mission12.into.fortress.L516.1714"] = "Resztką sił Kraknaknork wypycha cię ze swojej sali tronowej. Wracaj szybko i pokonaj go, zanim odzyska moc.",
  ["data.otservbr.global.scripts.quests.the.rookie.guard.mission12.into.fortress.L549.1715"] = "Gracz jest już w pokoju bossa.",
  ["data.otservbr.global.scripts.quests.the.rookie.guard.mission12.into.fortress.L564.1716"] = "Wchodzisz do sali tronowej Kraknaknorka. Masz 5 minut, aby go zabić!",
  ["data.otservbr.global.scripts.quests.the.rookie.guard.mission12.into.fortress.L595.1717"] = "Wycofałeś się z walki. Możesz spróbować ponownie w dowolnym momencie.",
  ["data.otservbr.global.scripts.quests.the.rookie.guard.mission12.into.fortress.L624.1718"] = "Nie możesz jeszcze użyć tego teleportera.",
  ["data.otservbr.global.scripts.quests.the.rookie.guard.mission12.into.fortress.L684.1719"] = "Znalazłeś",
  ["data.otservbr.global.scripts.quests.the.rookie.guard.mission12.into.fortress.L686.1720"] = "Znalazłeś",
  ["data.otservbr.global.scripts.quests.the.rookie.guard.mission12.into.fortress.L691.1721"] = "To",
  ["data.otservbr.global.scripts.quests.the.rookie.guard.mission12.into.fortress.L717.1722"] = "Dzięki ostatniemu źródłu energii Kraknaknorka uciekasz z fortecy. Czas wracać do Vascalira.",
  ["data.otservbr.global.scripts.quests.the.rookie.guard.mission12.into.fortress.L776.1723"] = "Znalazłeś",
  ["data.otservbr.global.scripts.quests.the.rookie.guard.mission12.into.fortress.L778.1724"] = "Znalazłeś",
  ["data.otservbr.global.scripts.quests.the.rookie.guard.mission12.into.fortress.L783.1725"] = "To",
  ["data.otservbr.global.scripts.quests.the.secret.library.quest.bursting.at.the.seams.museum.actions.doors.L18.2291"] = "Drzwi wydają się zapieczętowane przed nieproszonymi intruzami.",
  ["data.otservbr.global.scripts.quests.the.secret.library.quest.high.and.dry.isles.actions.telescope.L6.2318"] = "Teleskop zapewnia doskonały widok na bezkresny ocean - nie widać lądu.",
  ["data.otservbr.global.scripts.quests.the.secret.library.quest.high.and.dry.isles.movements.boat.puzzle.L13.2312"] = "Widzisz porozrzucane części rozbitego statku. Cudem okrętowy teleskop przetrwał wrak i wygląda na nienaruszony.",
  ["data.otservbr.global.scripts.quests.the.secret.library.quest.high.and.dry.isles.movements.boat.puzzle.L16.2313"] = "Wciąż są tu luźne deski i liny cumownicze. Nie możesz użyć tratwy w tym stanie, na pewno zatonie.",
  ["data.otservbr.global.scripts.quests.the.secret.library.quest.high.and.dry.isles.movements.boat.puzzle.L21.2314"] = "Używasz liny cumowniczej, aby związać luźne deski. Tratwa powinna być teraz zdatna do żeglugi.",
  ["data.otservbr.global.scripts.quests.the.secret.library.quest.high.and.dry.isles.movements.boat.puzzle.L27.2315"] = "Widzisz porozrzucane części rozbitego statku. Cudem okrętowy teleskop przetrwał wrak i wygląda na nienaruszony.",
  ["data.otservbr.global.scripts.quests.the.secret.library.quest.high.and.dry.isles.movements.boat.puzzle.L30.2316"] = "Bez punktów orientacyjnych nigdy nie znajdziesz drogi powrotnej. Spróbuj znaleźć sposób na poprawę nawigacji.",
  ["data.otservbr.global.scripts.quests.the.secret.library.quest.high.and.dry.isles.movements.stepIn.L91.2317"] = "Musisz poczekać. Ktoś wyzywa",
